(window.TNQ=window.TNQ||[]).push({"terms":{"조수해":{"d":"새나 짐승 때문에 농작물 등이 입는 피해.","r":[]},"보험가입금액":{"d":"보험에서 최대로 보상할 수 있는 한도액으로 가입자와 사업자가 약정한 금액.","r":["보험가액"]},"시범사업":{"d":"본격 시행 전에 보험의 효용성과 실시 가능성을 검증하려고 제한된 지역에서 일정 기간 해 보는 사업.","r":[]},"보험목적물":{"d":"보험의 대상이 되어 사고 때 보상의 대상이 되는 농작물, 임산물, 가축, 시설물 등.","r":[]},"재보험":{"d":"보험사업자가 떠안은 위험을 다시 다른 곳에 넘기는 보험으로, 이 법에서는 정부가 담당한다.","r":[]},"손해평가인":{"d":"재해보험사업자가 위촉해 피해 확인과 손해 평가를 맡기는 사람.","r":["손해평가사","손해평가반"]},"손해평가사":{"d":"자격시험에 합격해 피해사실 확인과 보험가액·손해액 평가를 하는 전문 자격자.","r":["손해평가인"]},"손해평가반":{"d":"손해평가를 하려고 사업자가 평가인 등으로 구성하는 조사 단위.","r":["손해평가인"]},"교차손해평가":{"d":"공정성을 위해 평가인끼리 담당 지역을 서로 바꾸어 평가하는 방식.","r":[]},"검증조사":{"d":"손해평가 결과가 맞는지 확인하려고 일부 목적물을 뽑아 다시 하는 조사.","r":["재조사"]},"재조사":{"d":"검증조사 결과 평가에 큰 차이가 나는 경우 같은 평가반이 조사한 목적물 전체를 다시 조사하는 것.","r":["검증조사"]},"현지조사서":{"d":"손해평가 결과와 평가에 참여한 평가반 구성원을 기록하는 서식.","r":[]},"보험가액":{"d":"보험목적물의 가치를 평가한 금액으로 손해 보상의 기준이 된다.","r":["보험가입금액"]},"재조달가액":{"d":"피해를 입은 목적물을 같은 것으로 다시 구입하거나 짓는 데 드는 비용.","r":["감가상각액"]},"감가상각액":{"d":"사용 기간에 따라 줄어든 목적물의 가치를 내용연수에 따라 계산한 금액.","r":["재조달가액"]},"자기부담비율":{"d":"손해가 났을 때 가입자가 스스로 책임지기로 정한 손해의 비율.","r":["피해율"]},"피해율":{"d":"수확량이나 면적, 나무 수 등을 기준으로 피해의 정도를 나타낸 비율.","r":["자기부담비율"]},"평년수확량":{"d":"과거 수확량 자료로 정한, 평년에 기대되는 수확량.","r":[]},"미보상감수량":{"d":"보상하지 않는 원인으로 줄어든 수확량.","r":[]},"착과수조사":{"d":"수확 직전이나 적과 후에 달려 있는 과실의 총 수를 조사하는 일.","r":[]},"경과비율":{"d":"생육 단계나 사고 시기에 따라 보험금에 반영하는 비율.","r":[]},"제현율":{"d":"벼를 찧어 겉껍질을 벗겼을 때 얻는 현미의 비율.","r":[]},"전수조사":{"d":"조사 대상 목적물을 빠짐없이 모두 조사하는 방법.","r":["표본조사"]},"표본조사":{"d":"통계이론으로 정한 표본만 골라 조사하는 방법.","r":["전수조사"]},"보험금수급전용계좌":{"d":"보험금만 입금되도록 수급권자 명의로 지정하는 계좌.","r":[]},"농어업재해재보험기금":{"d":"재보험사업에 필요한 재원을 마련하려고 설치하는 기금.","r":[]},"청문":{"d":"행정기관이 불이익한 처분을 하기 전에 당사자의 의견을 직접 듣는 절차.","r":[]},"가중처분":{"d":"같은 위반이 되풀이될 때 처분을 더 무겁게 하는 것.","r":[]}},"notes":{"(2021~2024 기출 당시 문구: 재해보험사업자 및 재해보험사업의 재보험사업자)":"예전 문구는 사업자와 재보험사업자를 검증조사 주체로 적었습니다.","(2021 기출 당시 「위촉하여야 한다」)":"예전에는 위촉해야 한다는 의무 규정이었으나 지금은 위촉할 수 있다는 임의 규정입니다.","(2021 기출 정답은 양배추, 현행 별표는 양파도 해당)":"현행 별표의 재정식조사 대상에는 양파도 들어 있어요.","(2022 기출 당시 10%: 가입금액 1,000만원 → 100만원)":"이전 기준에서는 가입금액 1,000만원의 10%인 100만원이 이앙·직파불능 보험금이었습니다.","(2022 기출 정답은 자두, 현행 별표는 사과ㆍ단감도 해당)":"현행 별표에는 사과와 단감도 착과수조사 대상에 들어 있습니다.","(2025-49 기출 당시: 2024년 1월 1일 기준 매 3년, 12월 31일까지)":"개정 전에는 기준 시점이 2024년 1월 1일이었고 3년째 12월 31일까지 검토했습니다.","(시행령 별표 2의4의 손해평가사 업무정지 기준은 ‘생계를 같이 하는 4촌 이내의 친족’)":"업무정지 기준에서는 생계를 같이하는 4촌 이내 친족이라고 범위를 더 좁혀 적습니다.","(잔존보험가입금액 × 경과비율 × 피해율) - 자기부담금":"브로콜리 생산비보장 보험금은 잔존보험가입금액에 경과비율과 피해율을 곱한 뒤 자기부담금을 뺍니다.","1(농업재해보험에 관한 기초지식): 농어업재해보험법 제정 배경ㆍ구성 및 조문별 주요내용, 농업재해보험 사업현황":"첫째 과목은 법 제정 배경과 구성, 조문별 주요 내용, 사업 현황 같은 기초지식입니다.","1. 재해보험사업의 발전 방향 및 목표":"기본계획에는 재해보험사업의 발전 방향과 목표가 들어갑니다.","1. 재해보험에서 보상하는 재해의 범위에 관한 사항":"보상하는 재해의 범위는 심의회에서 따져 봐야 하는 첫 번째 사항이에요.","1: 법 제11조제2항 및 요령의 규정을 위반한 때":"법 제11조제2항이나 요령 규정을 어기면 업무정지·해지 사유가 됩니다.","1: 보험가입자의 권리가 축소되거나 의무가 확대되는 내용의 보험약관안 변경":"가입자 권리가 줄거나 의무가 늘어나는 약관안 변경은 공고 대상입니다.","1: 손해평가사의 자격을 거짓 또는 부정한 방법으로 취득한 사람, 취소하여야 한다":"자격을 거짓이나 부정한 방법으로 얻은 사람은 반드시 취소해야 합니다.","1: 재해보험사업자가 정부에 내야 할 보험료(재보험료)에 관한 사항":"재보험 약정에는 사업자가 정부에 내는 재보험료에 관한 내용이 들어갑니다.","1: 피성년후견인 (2021ㆍ2023 기출 당시 피한정후견인으로 출제)":"피성년후견인은 위촉 취소 사유입니다.","1의2: 산림조합법에 따라 설립된 지역산림조합 및 품목별ㆍ업종별산림조합":"산림조합법에 따른 지역산림조합과 품목별·업종별 산림조합도 위탁 대상입니다.","1의2: 산림조합법에 따른 산림조합중앙회":"산림조합중앙회도 통계 업무를 위탁받을 수 있어요.","1호: 재해보험이나 농업에 관한 학식과 경험이 풍부하다고 인정되는 사람":"첫째 유형은 재해보험이나 농업에 학식과 경험이 풍부하다고 인정되는 사람입니다.","1회 6개월 / 2회 1년 / 3회 이상 1년":"정보보호 법령 위반은 첫 위반 6개월, 두 번째 1년, 세 번째 이상 1년의 업무정지입니다.","2(농업재해보험의 종류별 약관): 농업재해보험 상품 주요내용 및 약관 일반 사항":"둘째 과목은 상품 주요 내용과 약관 일반 사항을 다룹니다.","2. 재해보험사업에 대한 재정지원에 관한 사항":"재해보험사업에 대한 재정지원도 심의 대상입니다.","2. 재해보험의 종류별 가입률 제고 방안에 관한 사항":"종류별 가입률을 높일 방안도 기본계획에 담는 사항이에요.","2021~2023 기출 당시 평가인 등 1인 이상 포함 5인 이내 구성이라":"예전 요령은 평가인 등 1인 이상을 포함한 5인 이내 구성이라 보조인이 들어갈 수 있었습니다.","2: 거짓으로 손해평가를 한 사람":"손해평가를 거짓으로 한 사람도 자격 취소 사유에 해당해요.","2: 법 및 요령에 의한 명령이나 처분을 위반한 때":"법과 요령에 따른 명령이나 처분을 어긴 경우도 사유예요.","2: 보험가액 및 손해액 평가":"손해평가 업무에는 보험가액과 손해액을 평가하는 일이 포함됩니다.","2: 보험상품을 폐지하는 내용의 보험약관안 변경":"보험상품을 없애는 내용의 약관안 변경도 공고해야 해요.","2: 보험확대 예비품목(제3조제1항제2호에 따라 선정한 보험목적물 도입예정 품목)의 현황":"통계자료에는 보험확대 예비품목의 현황이 포함됩니다.","2: 재해보험사업자가 준수하여야 할 사항":"약정서에는 재해보험사업자가 지켜야 할 사항이 들어갑니다.","2: 재해보험 상품의 연구 및 보급":"재해보험 상품을 연구하고 널리 보급하는 일도 장관의 업무예요.","2: 정부, 정부 외의 자 및 다른 기금으로부터 받은 출연금":"기금의 재원 가운데 하나는 정부와 다른 기금 등에서 받은 출연금입니다.","2: 정부가 지급하여야 할 보험금(재보험금)에 관한 사항":"정부가 지급할 재보험금에 관한 사항도 약정에 담습니다.","2: 파산선고를 받은 자로서 복권되지 아니한 자, 위촉 당시 이미 복권되었다면 해당하지 않는다":"복권되지 않은 파산선고자는 취소 사유이며, 위촉 당시 이미 복권됐다면 해당하지 않아요.","2호: 농림축산식품부의 재해보험을 담당하는 3급 공무원 또는 고위공무원단에 속하는 공무원":"둘째 유형은 농림축산식품부에서 재해보험을 맡은 3급 공무원이나 고위공무원단 소속 공무원이에요.","3(손해평가의 절차 및 방법): 농업재해보험 손해평가 개요, 보험목적물별 손해평가 기준 및 피해유형별 보상사례":"셋째 과목은 평가 개요, 목적물별 평가 기준, 피해유형별 보상사례예요.","3. 손해평가의 방법(농업재해에 따른 피해율의 산정을 포함한다)과 절차에 관한 사항":"손해평가의 방법과 절차는 농업재해의 피해율 산정까지 포함해 심의 대상이에요.","3. 재해보험의 대상 품목, 대상 지역 및 상품 개발에 관한 사항":"대상 품목과 지역, 상품 개발에 관한 사항도 포함됩니다.","3: 그 밖에 손해평가에 관하여 필요한 사항":"그 밖에 손해평가에 필요한 사항도 업무에 해당해요.","3: 그 밖에 재보험수수료 등 대통령령으로 정하는 사항":"재보험수수료 등 대통령령으로 정하는 사항도 약정 내용이에요.","3: 기금의 관리ㆍ운용에 필요한 경비(위탁경비 포함)의 지출":"기금의 관리·운용에 드는 경비도 위탁경비를 포함해 기금에서 지출해요.","3: 법 제30조에 의하여 벌금 이상의 형을 선고받고 그 집행이 종료(종료된 것으로 보는 경우 포함)되거나 집행이 면제된 날부터 2년이 경과되지 아니한 자":"벌금 이상 형 집행이 끝나거나 면제된 날부터 2년이 지나지 않은 사람도 취소 사유입니다.","3: 보험상품 변경으로 기존 보험료율보다 높은 보험료율안으로의 변경":"보험료율이 기존보다 높아지는 변경 역시 공고 대상입니다.","3: 보험업법 제187조에 따라 손해사정을 업으로 하는 자":"손해사정을 업으로 하는 자도 업무 위탁 대상에 들어갑니다.","3: 업무수행과 관련하여 개인정보보호법, 신용정보의 이용 및 보호에 관한 법률 등 정보보호 관련 법령을 위반한 때, 위촉 취소가 아니라 업무정지ㆍ위촉 해지 사유":"정보보호 관련 법령 위반은 위촉 취소가 아니라 업무정지나 위촉 해지 사유입니다.","3: 재해 관련 통계 생산 및 데이터베이스 구축ㆍ분석":"재해 관련 통계를 만들고 데이터베이스를 구축·분석하는 것도 업무입니다.","3: 재해보험사업자에 대한 재정지원에 관한 사항, 「국가에 대한 재정지원」이라는 문구는 이 호가 아니다":"재해보험사업자에 대한 재정지원 사항이 이 호이며, 국가에 대한 재정지원이라는 표현은 맞지 않아요.","3: 제11조의4제6항을 위반하여 다른 사람에게 명의를 사용하게 하거나 자격증을 대여한 사람":"자격증을 대여하거나 명의를 쓰게 한 사람도 취소 사유입니다.","3호: 자연재해 또는 보험 관련 업무를 담당하는 재정경제부ㆍ행정안전부ㆍ해양수산부ㆍ기획예산처ㆍ금융위원회ㆍ산림청의 3급 공무원 또는 고위공무원단에 속하는 공무원":"셋째 유형은 자연재해나 보험 업무를 하는 여러 부처와 위원회의 3급 공무원 또는 고위공무원단 소속 공무원입니다.","4. 재보험사업에 대한 정부의 책임범위에 관한 사항":"재보험사업에서 정부가 어디까지 책임질지도 심의를 거쳐 정합니다.","4. 재해보험사업에 대한 지원 및 평가에 관한 사항":"재해보험사업을 지원하고 평가하는 방법도 기본계획에 담깁니다.","4: 그 밖에 장관이 해양수산부장관과 협의하여 재보험사업을 유지ㆍ개선하는 데 필요하다고 인정하는 경비의 지출":"그 밖에 재보험사업을 유지·개선하는 데 필요하다고 장관이 인정한 경비도 쓸 수 있습니다.","4: 기금의 운용수익금과 그 밖의 수입금":"기금을 운용해서 생긴 수익금과 그 밖의 수입금도 재원이에요.","4: 손해평가인력의 육성 및 재해보험 대상 품목에 대한 전문성 제고":"손해평가인력을 키우고 대상 품목에 대한 전문성을 높이는 것도 장관의 업무예요.","4: 약정의 변경ㆍ해지 등에 관한 사항":"약정의 변경과 해지 등에 관한 사항도 약정서에 담습니다.","4: 위촉이 취소된 후 2년이 경과하지 아니한 자":"위촉이 취소된 지 2년이 지나지 않은 사람도 다시 위촉될 수 없어 취소 사유예요.","4: 제11조의4제7항을 위반하여 명의 사용이나 자격증 대여를 알선한 사람":"명의 사용이나 자격증 대여를 알선한 사람도 취소 사유예요.","4: 품목별 재배 또는 양식 면적과 생산량 및 가격":"품목별 재배·양식 면적, 생산량, 가격이 통계자료에 들어갑니다.","4: 피해유형별 현지조사표 작성 실습":"넷째로 피해유형별 현지조사표 작성 실습을 합니다.","4호: 농림축산업인단체의 대표":"넷째 유형은 농림축산업인단체를 대표하는 사람이에요.","5. 그 밖에 재해보험 활성화를 위하여 농림축산식품부장관 또는 해양수산부장관이 필요하다고 인정하는 사항":"이 밖에 활성화에 필요하다고 장관이 인정한 사항도 기본계획에 들어갈 수 있어요.","5. 재보험사업 관련 자금의 수입과 지출의 적정성에 관한 사항":"재보험사업 자금의 수입과 지출이 적정한지도 심의 사항입니다.","5: 거짓 그 밖의 부정한 방법으로 위촉된 자":"거짓이나 부정한 방법으로 위촉된 사람은 취소 대상입니다.","5: 그 밖에 장관이 필요하다고 인정하는 통계자료":"그 밖에 장관이 필요하다고 인정하는 통계자료도 수집 대상입니다.","5: 그 밖에 재해보험사업의 운영에 관한 사항":"그 밖에 재해보험사업 운영에 관한 사항도 약정서에 적습니다.","5: 손해평가기법의 연구ㆍ개발 및 보급":"손해평가 기법을 연구·개발해서 보급하는 일도 장관의 업무입니다.","5: 업무정지 기간 중에 손해평가 업무를 수행한 사람, 취소하여야 한다":"업무정지 기간에 손해평가를 한 사람의 자격은 반드시 취소해야 합니다.","5년 이상 경작한 임업인 / 공무원(농림축산식품부, 농촌진흥청, 산림청, 통계청, 지방자치단체) 임산물재배 연구ㆍ지도 또는 임업 통계조사 3년 이상 / 고등학교 교원 임산물재배 관련 과목 5년 이상 / 조교수 이상 임산물재배 관련학 3년 이상 / 보험회사 또는 산림조합법 중앙회ㆍ조합 임직원 산림경영 지원 또는 보험ㆍ공제 업무 3년 이상 또는 손해평가 2년 이상 / 임산물재배 관련학 전공 후 임업전문 연구기관 5년 이상 근무 학사 이상 / 전문대 보험 관련 학과 졸업(예정) / 학점인정 등 동등 학력(80학점, 보험 관련 45학점) / 임산물 분야 기사 이상":"임산물 분야의 손해평가인 자격은 임업 경작 경력, 관련 공무원·교원·교수, 보험 업무 경력자 등으로 정해집니다.","5년 이상 사육한 경력의 농업인 / 공무원 가축사육 연구ㆍ지도 또는 가축 통계조사 3년 이상 / 고등학교 교원 가축사육 관련 과목 5년 이상 / 조교수 이상 가축사육 관련학 3년 이상 / 보험회사 또는 농협 중앙회ㆍ조합 임직원 3년(보험ㆍ공제)ㆍ2년(손해평가) / 가축사육 관련학 전공 후 축산전문 연구기관 5년 이상 근무 학사 이상 / 전문대 보험 관련 학과 / 학점인정 등 동등 학력 / 수의사 / 축산기사 이상":"가축 분야는 사육 경력 농업인, 관련 공무원·교원·교수, 보험 업무 경력자, 수의사, 축산기사 등이 자격 대상입니다.","5년 이상 양식한 경력의 어업인 / 공무원(해양수산부, 국립수산과학원, 국립수산물품질관리원, 지방자치단체) 수산물양식 또는 수산생명의학 연구ㆍ지도 3년 이상 / 수산계 고등학교 교원 5년 이상 / 조교수 이상 관련학 3년 이상 / 보험회사 또는 수협중앙회ㆍ수협은행ㆍ조합 임직원 3년ㆍ2년 / 관련학 전공 후 수산전문 연구기관 5년 이상 근무 학사 소지자 / 전문대 보험 관련 학과 / 학점인정 등 동등 학력 / 수산질병관리사 / 양식수산물 분야 기사 이상 / 수산물품질관리사":"양식수산물 분야는 양식 경력 어업인, 관련 공무원·교원, 보험 업무 경력자, 수산질병관리사 등이 대상입니다.","6. 그 밖에 심의회 위원장이 회의에 부치는 사항":"심의회 위원장이 회의에 부치는 그 밖의 사항도 심의 대상이 되죠.","6: 농어촌구조개선 특별회계법 제5조제2항제7호에 따라 농어촌특별세사업계정으로부터 받은 전입금":"농어촌특별세사업계정에서 받은 전입금도 기금 재원입니다.","6: 업무정지 기간 중에 손해평가업무를 수행한 자":"업무정지 기간 중에 평가 업무를 한 사람도 위촉 취소 사유예요.","MIN(보험가입금액, 손해액) - 자기부담금":"옥수수는 가입금액과 손해액 중 작은 값에서 자기부담금을 뺀 금액이 보험금입니다.","MIN(손해액 - 자기부담금, 보험가입금액)":"비가림시설은 손해액에서 자기부담금을 뺀 값과 가입금액 중 작은 쪽이 보험금입니다.","‘이해관계자가 실시한 손해평가에 대한 검증조사’는 배제 사유에 없다":"이해관계자가 한 평가에 대한 검증조사는 배제 사유에 열거되어 있지 않아요.","‘자기와 생계를 같이 하는 친족’":"이해관계자는 자기와 생계를 같이하는 친족을 말합니다.","「금융상품직접판매업자」는 「보험사업자」로 본다":"금융소비자 보호법의 금융상품직접판매업자는 이 법에서 보험사업자로 읽습니다.","「하여야 한다」가 아니라 「할 수 있다」":"재조사는 의무가 아니라 할 수 있다는 재량 규정입니다.","가: 금융위원회의 설치 등에 관한 법률에 따라 설립된 금융감독원":"첫 번째 기관은 금융위원회 설치법에 따라 설립된 금융감독원이에요.","가입면적, 연근 등이 가입 당시와 다르면 변경할 수 있다":"가입면적이나 연근이 가입 당시와 다르면 보험가액을 바꿀 수 있어요.","가입면적, 주수, 수령, 품종 등이 다르면 변경할 수 있다":"가입면적, 주수, 수령, 품종이 달라지면 보험가액도 바꿀 수 있어요.","가입면적 등이 다르면 변경할 수 있다":"가입면적 등이 다를 때는 이 보험가액도 변경할 수 있어요.","가입면적에 보험가입 당시의 단위당 가입가격을 곱하여 산정":"인삼 보험가액은 가입면적에 가입 당시 단위당 가입가격을 곱해 구합니다.","가입자 자격 확인 사무에 불가피하면 주민등록번호가 포함된 자료를 처리할 수 있다":"가입자 자격 확인에 꼭 필요하면 주민등록번호가 담긴 자료도 처리할 수 있어요.","가중처분은 최근 3년간 같은 위반행위로 행정처분을 받은 경우에 적용":"과거 3년 안에 같은 위반으로 처분받았다면 이번 처분을 더 무겁게 하는 가중이 적용됩니다.","가축과 축산시설물은 가축재해보험 목적물이고 농작물재해보험 목적물이 아니다":"가축과 축산시설물은 가축재해보험의 목적물이라서 농작물재해보험으로는 보장받지 못합니다.","가축은 수량 × 적용가격(보험가액ㆍ손해액 모두)":"가축은 보험가액과 손해액 모두 수량에 적용가격을 곱해 구해요.","감가상각액을 차감하는 규정이 없다, 감가상각은 농업시설물에만 있다":"가축 보험가액에는 감가상각을 빼는 규정이 없고 감가상각은 농업시설물에만 있어요.","감귤(온주밀감류)(가입면적): 5,000㎡ 미만 4 / 10,000㎡ 미만 6 / 10,000㎡ 이상 8":"감귤 온주밀감류는 가입면적이 5,000㎡ 미만이면 4주, 10,000㎡ 이상이면 8주를 표본으로 합니다.","감귤(온주밀감류)만 해당: 사고접수 후 지체 없이, 표본주의 과실 구분(표본조사)":"수확전사고조사는 감귤(온주밀감류)만 해당하며 표본주의 과실을 구분해 표본조사합니다.","감자, 차, 콩, 팥, 수박, 당근, 생강, 고랭지무, 가을무(일반무), 가을배추: 2,500㎡ 미만 4 / 2,500~5,000 미만 5 / 5,000~7,500 미만 6 / 7,500~10,000 미만 7 / 10,000㎡ 이상 8":"감자·콩·수박 등은 2,500㎡ 미만 4구간에서 10,000㎡ 이상 8구간까지 표본구간을 정합니다.","같은 시ㆍ군ㆍ구에서도 할 수 있다":"같은 시·군·구 안에서도 교차손해평가를 할 수 있습니다.","거대재해 발생, 평가인력 부족 등으로 신속한 손해평가가 불가피하다고 판단되는 경우에는 지역손해평가인을 포함하지 않을 수 있다":"거대재해나 인력 부족으로 신속한 평가가 불가피하면 지역손해평가인을 포함하지 않을 수 있어요.","거짓ㆍ부정 취득 — 자격 취소 / 거짓으로 손해평가 — 시정명령(2회 이상 위반 시 자격 취소) / 명의 사용ㆍ자격증 대여 — 자격 취소 / 명의 사용ㆍ대여 알선 — 자격 취소 / 업무정지 기간 중 업무 수행 — 자격 취소":"부정 취득·명의 대여·알선·업무정지 중 업무는 취소이고, 거짓 평가는 시정명령 뒤 2회 이상이면 취소예요.","검증조사 결과 부당ㆍ부실 손해평가로 확인된 경우: 1차 경고, 2차 업무정지 3개월, 3차 위촉해지":"검증조사로 부당·부실이 확인되면 경고, 업무정지 3개월, 위촉해지의 순으로 나아갑니다.","검증조사결과 현저한 차이가 발생되어 재조사가 불가피하다고 판단될 경우에는 해당 손해평가반이 조사한 전체 보험목적물에 대하여 재조사를 할 수 있다":"검증조사에서 현저한 차이가 나 재조사가 불가피하면 그 평가반이 조사한 전체 목적물을 재조사할 수 있어요.","결산 개요 / 수입지출결산 / 재무제표 / 성과보고서 / 그 밖에 결산 내용을 명확하게 하기 위한 서류":"결산보고서에는 결산 개요, 수입지출결산, 재무제표, 성과보고서 등이 첨부됩니다.","경감: 사소한 부주의 등은 2분의 1 범위에서 줄일 수 있다":"사소한 부주의 등은 정지 기간을 2분의 1 범위에서 줄여 줄 수 있습니다.","경과비율(사고발생일이 속한 월): 5월 — 벼 80%, 옥수수 80% / 6월 — 벼 85%, 옥수수 80% / 7월 — 벼 90%, 옥수수 90% / 8월 — 벼 100%, 옥수수 100%":"경과비율은 사고가 난 달에 따라 달라서 5월 벼·옥수수는 80%, 8월은 모두 100%입니다.","경사지에서 보이는 돌담 등으로 구획된 면적이 극히 작은 것은 동일 작업 단위 등으로 정리하여 하나의 농지에 포함할 수 있다":"경사지에서 돌담으로 나뉜 아주 작은 면적은 동일 작업 단위로 묶어 한 농지에 넣을 수 있어요.","경작불능조사: 사고접수 후 지체 없이, 해당 농지의 피해면적비율 또는 보험목적인 식물체 피해율 조사":"경작불능조사는 사고접수 후 곧바로 피해면적비율이나 식물체 피해율을 조사합니다.","계산 예(2022 기출): 보험가입금액 1,000만원, 피해율 50%, 자기부담비율 20% → 1,000만원 × (0.5 - 0.2) = 300만원":"가입금액 1,000만원에 피해율 50%에서 자기부담 20%를 뺀 값을 곱하면 300만원이에요.","계산 예(2025 기출): 보험가입금액 100만원, 자기부담비율 20%, 피해주수 50, 실제결과주수 100 → 100만원 × (0.5 - 0.2) = 30만원":"피해주수 50, 실제결과주수 100이면 피해율 0.5에서 0.2를 뺀 값을 곱해 30만원이 됩니다.","계산 예(2025 기출): 보험가입금액 100만원 → 100만원 × 15% = 15만원":"가입금액 100만원의 15%를 곱하면 15만원이 이앙·직파불능 보험금입니다.","고구마, 양파, 마늘, 옥수수, 양배추, 단호박: 1,500㎡ 미만 4 / 1,500~3,000 미만 5 / 3,000~4,500 미만 6 / 4,500㎡ 이상 7":"고구마·양파·마늘 등은 1,500㎡ 미만 4구간에서 4,500㎡ 이상 7구간까지 표본구간을 정해요.","고등교육법 제2조에 따른 전문대학에서 보험 관련 학과를 졸업했거나 졸업 예정인 사람":"전문대학에서 보험 관련 학과를 졸업했거나 졸업 예정인 사람도 자격이 됩니다.","고등교육법 제2조에 따른 학교에서 농작물재배 관련학을 전공하고 농업전문 연구기관 또는 연구소에서 5년 이상 근무한 학사학위 이상 소지자":"농작물재배 관련학 전공자가 농업전문 연구기관에서 5년 이상 일한 학사 이상 소지자도 해당합니다.","고사나무조사: 수확완료 후~보험 종기 전, 보상하는 재해로 고사되거나 회생이 불가능한 나무 수, 특약 가입 농지만 해당, 전수조사, 추가 고사나무가 없으면 생략 가능":"고사나무조사는 수확완료 후 보험 종기 전에 특약 가입 농지에서 전수조사하며 추가 고사가 없으면 생략합니다.","고사나무조사 — 수확완료 후 보험 종기 전, 보상하는 재해로 고사되거나 회생이 불가능한 나무 수 조사, 특약 가입 농지만 해당, 전수조사, 수확완료 후 추가 고사나무가 없는 경우 생략 가능":"고사나무조사는 수확완료 후 보험 종기 전에 고사하거나 회생이 불가능한 나무 수를 특약 농지에서 전수조사합니다.","고시된 면제신청서에 증명서류를 첨부하여 농림축산식품부장관에게 신청":"면제를 받으려면 면제신청서에 증명서류를 붙여 농림축산식품부장관에게 신청합니다.","고의 또는 중대한 과실로 손해평가의 신뢰성을 크게 악화시킨 경우 / 고의로 진실을 숨기거나 거짓 손해평가 / 정당한 사유 없이 손해평가반 구성 거부 / 현장조사 없이 보험금 산정을 위해 손해평가행위 / 현지조사서 허위 작성":"고의·중과실로 신뢰성을 크게 해친 경우나 거짓 평가, 현지조사서 허위 작성은 처음 위반부터 위촉해지입니다.","고의성이 없거나 특별한 사유가 있으면 업무정지는 2분의 1 범위에서 경감, 위촉해지는 업무정지 6개월로, 경고는 주의로 경감할 수 있다":"고의가 없거나 사정이 있으면 업무정지는 2분의 1 범위로 줄이고 해지는 정지 6개월로, 경고는 주의로 낮출 수 있어요.","고추, 메밀, 브로콜리, 배추(봄배추, 고랭지배추, 월동배추), 무, 파, 시금치, 양상추, 두릅, 노지오이(실제경작면적 또는 피해면적): 3,000㎡ 미만 4 / 3,000~7,000 미만 6 / 7,000~15,000 미만 8 / 15,000㎡ 이상 10 (표본구간 또는 이랑 수)":"고추·배추·무·파 등은 3,000㎡ 미만 4에서 15,000㎡ 이상 10까지로, 표본구간 또는 이랑 수입니다.","공고사항: 시험의 일시ㆍ장소 / 시험방법ㆍ과목 / 응시원서 제출방법ㆍ응시수수료 / 합격자 발표의 일시ㆍ방법 / 선발예정인원(수급상 필요하여 정한 경우만) / 그 밖에 시험 실시에 필요한 사항":"공고에는 일시·장소, 방법·과목, 응시 방법과 수수료, 합격자 발표, 선발예정인원 등이 들어갑니다.","공무원으로 농림축산식품부, 농촌진흥청, 통계청, 지방자치단체나 그 소속기관에서 농작물재배 분야 연구ㆍ지도, 농산물 품질관리 또는 농업 통계조사 업무를 3년 이상 담당한 경력":"농작물 연구·지도·품질관리·통계조사 업무를 3년 이상 한 관련 기관 공무원도 자격이 있어요.","공익법인의 설립ㆍ운영에 관한 법률 제4조에 따라 장관의 허가를 받아 설립된 공익법인":"공익법인법에 따라 장관 허가로 설립된 공익법인도 통계 업무 위탁 대상입니다.","과실손해보장: 보험가입금액 × (피해율 - 자기부담비율)":"무화과 과실손해 보험금은 가입금액에 피해율과 자기부담비율의 차를 곱한 값이에요.","과실손해보험금 = (적과 종료 이후 누적감수량 - 자기부담감수량) × 가입가격":"과실손해보험금은 적과 종료 이후 누적감수량에서 자기부담감수량을 뺀 양에 가입가격을 곱합니다.","과실손해보험금 = 손해액 - 자기부담금, 손해액 = 보험가입금액 × 피해율, 자기부담금 = 보험가입금액 × 자기부담비율":"감귤 과실손해보험금은 손해액에서 자기부담금을 뺀 값이고 손해액은 가입금액에 피해율을 곱해 구합니다.","과실손해조사: 수확 직전, 사고발생 농지의 과실피해조사(표본조사), 무화과, 감귤(온주밀감류)만 해당":"과실손해조사는 수확 직전에 과실 피해를 표본조사하며 무화과와 감귤(온주밀감류)에만 해당합니다.","과실손해조사 — 무화과(태풍(강풍)ㆍ우박): 사고접수 후 지체 없이, 표본주의 고사 및 정상 결과지수 조사(표본조사)":"무화과 과실손해조사는 태풍·우박 사고 뒤 표본주의 고사 및 정상 결과지 수를 조사해요.","과실손해조사 — 복분자(태풍(강풍)ㆍ우박, 6월 1일~6월 20일 사고 건에 한함): 사고접수 후 지체 없이, 전체 열매수(전체 개화수) 및 수확 가능 열매수 조사(표본조사)":"복분자 과실손해조사는 태풍·우박으로 입은 6월 1일~6월 20일 사고에 한해 전체 열매수와 수확 가능 열매수를 표본조사합니다.","과오납은 과오납한 금액 전부 / 시험일 20일 전까지 접수 취소는 전부 / 시험관리기관 귀책사유로 응시하지 못하면 전부 / 시험일 10일 전까지 접수 취소는 100분의 60":"과오납과 20일 전 취소, 관리기관 귀책은 전액, 시험일 10일 전까지 취소하면 100분의 60을 돌려받습니다.","과태료가 아니라 징역ㆍ벌금 대상이고, 동시에 자격 취소 사유이기도 하다":"자격증 대여는 과태료가 아니라 징역·벌금 대상이며 동시에 자격 취소 사유가 됩니다.","교원으로 고등학교에서 농작물재배 분야 관련 과목을 5년 이상 교육한 경력":"고등학교에서 농작물재배 관련 과목을 5년 이상 가르친 교원도 요건을 갖춥니다.","교차손해평가를 위해 손해평가반을 구성할 경우 선발된 지역손해평가인 1인 이상이 포함되어야 한다":"교차평가용 평가반에는 선발된 지역손해평가인이 한 명 이상 들어가야 합니다.","구체적 범위는 농업재해보험심의회 또는 중앙 수산업ㆍ어촌정책심의회를 거쳐 농림축산식품부장관 또는 해양수산부장관이 고시":"보험목적물의 구체적 범위는 심의회를 거친 뒤 담당 장관이 고시로 정합니다.","구체적인 보험가입자의 기준은 대통령령으로 정한다":"가입자의 구체적 기준은 법이 아니라 대통령령에서 정합니다.","그것도 안 되면 수급권자 본인의 신분증명서 확인을 거쳐 직접 현금으로 지급할 수 있다":"그것도 안 되면 본인 신분증명서를 확인한 뒤 직접 현금으로 줄 수 있어요.","그 밖에 기본계획 및 시행계획의 수립ㆍ변경ㆍ시행에 필요한 사항은 대통령령으로 정한다":"이 밖에 계획의 수립·변경·시행에 관한 세부 사항은 대통령령에서 정합니다.","그 밖에 직무를 게을리하거나 부적절한 행위를 한 경우 — 경고/1개월/3개월":"그 밖에 직무태만이나 부적절한 행위도 경고, 1개월, 3개월로 처분해요.","그 밖의 세부사항은 손해평가업무방법서와 보험약관에 따른다":"이 조사의 나머지 세부 방법은 사업자의 업무방법서와 약관이 정합니다.","금융감독원, 한국은행, 대학은 통계 업무 위탁 대상으로 열거되어 있지 않다":"금융감독원, 한국은행, 대학은 시행령이 통계 업무 위탁 대상으로 나열한 곳에 속하지 않습니다.","금융위원회가 아니라 농림축산식품부장관 또는 해양수산부장관":"이 경우의 과태료 부과권자는 금융위원회가 아니라 농림축산식품부장관 또는 해양수산부장관이에요.","금품 제공 3년/3천만 / 무자격 모집ㆍ거짓 손해평가ㆍ명의 대여ㆍ알선 1년/1천만 / 회계 구분 위반 500만원 벌금":"금품 제공은 징역 3년·벌금 3천만, 무자격 모집 등은 1년·1천만, 회계 구분 위반은 벌금 500만원입니다.","기금수입징수관의 업무를 수행":"기금수입담당임원은 기금수입징수관이 하던 업무를 수행합니다.","기금수탁관리자(농업정책보험금융원)는 기금을 다른 회계와 구분하여 회계처리하여야 한다":"기금수탁관리자는 기금을 다른 회계와 구분해서 회계처리해야 해요.","기금수탁관리자가 회계연도마다 작성하여 다음 회계연도 2월 15일까지 농림축산식품부장관 및 해양수산부장관에게 제출":"기금결산보고서는 수탁관리자가 회계연도마다 만들어 다음 회계연도 2월 15일까지 두 장관에게 냅니다.","기금은 농림축산식품부장관이 해양수산부장관과 협의하여 관리ㆍ운용":"기금의 운용은 농림축산식품부장관이 맡되 해양수산부장관과 협의를 거쳐야 합니다.","기금의 관리ㆍ운용에 관한 회계업무 / 재보험료를 납입받는 업무 / 재보험금을 지급하는 업무 / 여유자금의 운용업무 / 그 밖에 장관이 해양수산부장관과 협의하여 지정ㆍ고시하는 업무":"위탁 사무에는 회계, 재보험료 수납, 재보험금 지급, 여유자금 운용 등이 있습니다.","기금출납공무원의 업무를 수행":"기금출납원은 기금출납공무원의 업무를 수행해요.","기누적피해율은 보험기간 내 과거 보험사고 누적피해율 중 최대값":"기누적피해율은 보험기간 중 과거 사고의 누적피해율 가운데 가장 큰 값이에요.","기본계획ㆍ시행계획의 수립ㆍ시행을 위해 필요하면 관계 중앙행정기관의 장, 지방자치단체의 장, 관련 기관ㆍ단체의 장에게 자료와 정보의 제공을 요청할 수 있다":"필요하면 관계 기관 장에게 자료와 정보를 내 달라고 요청할 수 있어요.","기본계획과 시행계획을 수립하려면 제26조의 통계자료를 반영하여야 한다":"기본계획과 시행계획을 세울 때는 법에 정해진 통계자료를 반영해야 합니다.","기본계획에 따라 매년 재해보험 발전 시행계획을 수립ㆍ시행":"시행계획은 기본계획을 근거로 해마다 세우고 시행하는 계획입니다.","기본계획을 수립하거나 변경한 때에는 국회 소관 상임위원회에 보고하여야 한다":"기본계획을 세우거나 바꾸면 국회의 소관 상임위원회에 알려야 해요.","기재된 보험목적물이 나무인 경우, 최초 보험사고 발생 시 해당 농지 내에 심어져 있는 과실생산이 가능한 나무 수(피해 나무 수 포함)에 보험가입 당시의 나무당 가입가격을 곱하여 산정":"나무손해보장은 과실을 생산할 수 있는 나무 수에 나무당 가입가격을 곱해 보험가액을 구합니다.","기준: 보상하는 재해로 인한 피해의 범위 및 정도를 행정구역별ㆍ권역별 및 보험목적물별로 산출한 값의 상위 100분의 10에 해당하는 값":"그 기준은 피해 범위와 정도를 구역·권역·목적물별로 산출한 값 가운데 상위 100분의 10에 해당하는 값이에요.","기준 수확량 1,000kg(문제에서 보장수확량으로 제시), 수확량 500kg, 미보상감수량 50kg → 피해율 (1,000 - 500 - 50) ÷ 1,000 = 45%":"기준 수확량 1,000kg에서 수확량 500kg과 미보상감수량 50kg을 빼 1,000으로 나누면 피해율 45%예요.","기출 빈칸: 「보험가입금액 × ( ) × 10%」의 빈칸은 주계약피해율":"추가보장 식에서 비워 둔 곳에 들어갈 값은 주계약피해율입니다.","기타 업무수행상 과실로 손해평가의 신뢰성을 약화시킨 경우: 1차 주의, 2차 경고, 3차 업무정지 3개월":"과실로 신뢰성을 약화시킨 경우는 주의, 경고, 업무정지 3개월의 순서입니다.","나: 농업협동조합중앙회(농협손해보험이 설립되기 전까지의 중앙회에 한정)":"농협손해보험이 설립되기 전까지의 농업협동조합중앙회에 한해 경력을 인정합니다.","나무손해보장 = 보험가입금액 × (피해율 - 자기부담비율), 피해율 = 피해주수(고사된 나무) ÷ 실제결과주수":"나무손해보장은 가입금액에 피해율과 자기부담비율의 차를 곱하고, 피해율은 고사 나무를 실제결과주수로 나눈 값이에요.","낙과피해조사(사과ㆍ배ㆍ단감ㆍ떫은감): 사고접수 후 지체 없이, 재해로 떨어진 피해과실수 조사, 과실피해분류기준에 따라 구분, 전수조사 또는 표본조사":"수확 시작 후 낙과피해조사는 떨어진 피해과실수를 분류기준에 따라 조사합니다.","낙과피해조사 — 사고접수 후 지체 없이, 재해로 떨어진 피해과실수 조사, 보험약관의 과실피해분류기준에 따라 구분, 전수조사 또는 표본조사":"낙과피해조사는 재해로 떨어진 피해과실수를 분류기준에 따라 전수 또는 표본조사합니다.","낙엽률 조사(우박 및 일소 제외) — 낙엽피해정도 조사(표본조사), 단감ㆍ떫은감":"낙엽률 조사는 우박과 일소를 제외하고 단감·떫은감의 낙엽피해 정도를 표본조사해요.","내용: 농어업재해의 발생 빈도, 농어업재해의 피해 정도, 그 밖에 현황 파악에 필요하다고 인정하는 사항":"실태조사 내용은 재해 발생 빈도, 피해 정도, 그리고 현황 파악에 필요한 그 밖의 사항입니다.","농로는 구획 기준이 아니다, 농로로 나뉘어도 별도 농지가 되지 않는다":"농로는 구획 기준이 아니므로 농로로 나뉘어도 별개의 농지가 되지 않아요.","농림축산식품부장관ㆍ해양수산부장관 및 지방자치단체의 장은 지원 금액을 재해보험사업자에게 지급하여야 한다":"지원금은 장관과 지자체장이 재해보험사업자에게 지급합니다.","농림축산식품부장관과 해양수산부장관은 기본계획과 시행계획을 효과적으로 수립ㆍ시행하기 위하여 농어업재해의 발생 빈도 및 피해 정도 등 현황에 대한 실태조사를 할 수 있다":"두 장관은 계획을 효과적으로 세우려고 재해 발생 빈도와 피해 정도 등을 실태조사할 수 있어요.","농림축산식품부장관과 해양수산부장관은 농업재해보험심의회 또는 중앙 수산업ㆍ어촌정책심의회의 심의를 거쳐 재해보험 발전 기본계획을 5년마다 수립ㆍ시행하여야 한다":"재해보험 발전 기본계획은 두 장관이 심의회 심의를 거쳐 5년마다 세워 시행하는 계획이에요.","농림축산식품부장관과 해양수산부장관은 손해평가 요령에 따라 손해평가 결과를 검증하기 위한 조사를 실시할 수 있다":"장관은 손해평가 결과가 맞는지 검증하는 조사를 직접 실시할 수 있어요.","농림축산식품부장관 또는 해양수산부장관":"이 과태료는 농림축산식품부장관 또는 해양수산부장관이 부과합니다.","농림축산식품부장관 또는 해양수산부장관은 손해평가인 간의 손해평가에 관한 기술ㆍ정보의 교환을 지원할 수 있다, 금지하는 규정이 아니다":"장관은 평가인끼리 기술과 정보를 주고받도록 지원할 수 있으며 이를 금지하지 않습니다.","농림축산식품부장관 또는 해양수산부장관은 손해평가인의 공정하고 객관적인 손해평가와 전문성 향상을 위하여 연 1회 이상 정기교육을 실시하여야 한다, 대상은 손해평가인":"장관은 손해평가인을 대상으로 해마다 1회 이상 정기교육을 해야 합니다.","농림축산식품부장관 또는 해양수산부장관은 재보험에 가입하려는 재해보험사업자와 재보험 약정을 체결하여야 한다":"재보험에 가입하려는 사업자와 장관이 재보험 약정을 맺어야 합니다.","농림축산식품부장관 또는 해양수산부장관이 행정구역과 따로 구분하여 고시하는 지역 단위":"권역은 행정구역과 따로 장관이 고시하는 지역 단위입니다.","농림축산식품부장관 소속으로 농업재해보험심의회를 둔다":"농업재해보험심의회는 농림축산식품부장관 소속으로 두는 기구입니다.","농림축산식품부장관은 공정하고 객관적인 손해평가를 촉진하기 위하여 손해평가사 제도를 운영":"손해평가사 제도는 공정하고 객관적인 평가를 촉진하려고 농림축산식품부장관이 운영합니다.","농림축산식품부장관은 기금 운용에 필요하면 해양수산부장관과 협의하여 기금의 부담으로 금융기관, 다른 기금 또는 다른 회계로부터 자금을 차입할 수 있다":"기금 운용에 필요하면 금융기관·다른 기금·회계에서 기금 부담으로 돈을 빌릴 수 있습니다.","농림축산식품부장관은 손해평가사가 직무를 게을리하거나 직무를 수행하면서 부적절한 행위를 하였다고 인정하면 1년 이내의 기간을 정하여 업무의 정지를 명할 수 있다":"직무를 게을리하거나 부적절한 행위를 하면 장관이 1년 이내의 기간으로 업무정지를 명할 수 있습니다.","농림축산식품부장관은 손해평가사의 손해평가 능력 및 자질 향상을 위하여 교육을 실시할 수 있다":"장관은 손해평가사의 능력과 자질을 높이는 교육을 실시할 수 있어요.","농림축산식품부장관은 손해평가사 자격 취소와 업무 정지 처분을 하려면 청문을 하여야 한다":"손해평가사의 자격 취소나 업무정지 처분을 하기 전에는 청문을 해야 합니다.","농림축산식품부장관은 이 고시에 대하여 2026년 7월 1일 기준으로 매 3년이 되는 시점(매 3년째의 6월 30일까지)마다 타당성을 검토하여 개선 등의 조치를 하여야 한다":"장관은 이 고시를 일정 기준일부터 매 3년이 되는 시점마다 타당성을 검토해 개선해야 해요.","농림축산식품부장관은 재해보험사업자로 하여금 검증조사를 하게 할 수 있다":"농림축산식품부장관은 사업자에게 검증조사를 하도록 지시할 수 있어요.","농림축산식품부장관은 제1호 위원이 심신장애로 직무를 수행할 수 없게 된 경우, 직무 관련 비위사실이 있는 경우, 직무태만ㆍ품위손상 등으로 적합하지 않다고 인정되는 경우, 스스로 직무 수행이 곤란하다고 밝히는 경우 해촉할 수 있다":"학식·경험 위원이 장애, 비위, 직무태만 등으로 맡기 어렵거나 스스로 곤란하다고 하면 장관이 해촉할 수 있습니다.","농림축산식품부장관은 해양수산부장관과 협의를 거쳐 재보험사업에 관한 업무의 일부를 농업정책보험금융원에 위탁할 수 있다":"두 장관의 협의를 거쳐 재보험 실무 일부는 농업정책보험금융원이 대신 처리할 수 있습니다.","농림축산식품부장관은 해양수산부장관과 협의하여 검토한 후 심의회의 심의를 거쳐 다음 회계연도 2월 말일까지 재정경제부장관에게 제출":"장관은 해양수산부장관과 검토하고 심의회 심의를 거친 뒤 재정경제부장관에게 보고서를 넘깁니다.","농림축산식품부장관은 해양수산부장관과 협의하여 공동으로 재보험사업에 필요한 재원에 충당하기 위하여 농어업재해재보험기금을 설치":"재보험사업에 쓸 재원을 마련하려고 두 장관이 공동으로 농어업재해재보험기금을 설치합니다.","농림축산식품부장관은 해양수산부장관과 협의하여 기금의 수입과 지출을 명확히 하기 위하여 한국은행에 기금계정을 설치하여야 한다":"기금의 수입과 지출을 분명히 하려고 한국은행에 기금계정을 설치해야 합니다.","농림축산식품부장관은 해양수산부장관과 협의하여 소속 공무원 중에서 기금수입징수관, 기금재무관, 기금지출관, 기금출납공무원을 임명":"기금수입징수관 등 회계기관은 장관이 소속 공무원 중에서 임명합니다.","농림축산식품부장관이 고시하는 가축을 사육하는 자":"가축재해보험은 장관이 고시한 가축을 사육하는 사람이 가입할 수 있어요.","농림축산식품부장관이 고시하는 농작물을 재배하는 자":"농작물재해보험의 대상자는 장관이 고시한 농작물을 재배하는 사람입니다.","농림축산식품부장관이 고시하는 임산물을 재배하는 자":"임산물재해보험은 장관이 고시한 임산물을 재배하는 사람이 가입 대상이에요.","농림축산식품부장관이 인정하는 자가 아니다":"인정 주체는 중앙회장이나 조합장이며 농림축산식품부장관이 인정하는 것은 아닙니다.","농수산물 품질관리법에 따른 농산물품질관리사":"농수산물 품질관리법에 따른 농산물품질관리사도 손해평가인이 될 수 있어요.","농어업재해 관련 전문성과 인력을 갖춘 연구기관ㆍ법인 또는 단체에 의뢰하여 실시할 수 있다":"재해 분야 전문성과 인력을 갖춘 연구기관·법인·단체에 맡겨 실시할 수도 있습니다.","농어업재해로 발생하는 농작물, 임산물, 양식수산물, 가축과 농어업용 시설물의 피해에 따른 손해를 보상하기 위한 농어업재해보험에 관한 사항을 규정":"이 법은 농어업재해로 생긴 농작물·가축·시설 등의 재산 피해를 보험으로 보상하는 일에 관한 사항을 정합니다.","농어업재해로 발생하는 재산 피해에 따른 손해를 보상하기 위한 보험":"농어업재해보험은 재해로 생긴 재산 피해의 손해를 메워 주는 보험입니다.","농어업재해보험 관련 업무를 수행할 목적으로 민법 제32조에 따라 농림축산식품부장관 또는 해양수산부장관의 허가를 받아 설립된 비영리법인":"민법에 따라 장관 허가를 받아 세운 비영리법인으로 재해보험 업무를 수행하는 곳도 위탁 대상이에요.","농어업재해보험법 제11조제2항에 따른 손해평가에 필요한 세부사항을 규정":"이 요령은 농어업재해보험법의 손해평가에 필요한 세부사항을 정한 고시입니다.","농업수입감소보험금 = 보험가입금액 × (피해율 - 자기부담비율)":"농업수입감소보험금은 가입금액에 피해율과 자기부담비율의 차를 곱해 구해요.","농업시설물ㆍ버섯재배사ㆍ부대시설: 한 사고마다 재조달가액(재조달가액보장 특약 미가입 시 시가) 기준으로 계산한 손해액에서 자기부담금을 차감한 금액을 보험가입금액 내에서 보상, 단 수리ㆍ복구를 하지 않은 경우 시가로 손해액을 계산":"농업시설물은 재조달가액으로 낸 손해액에서 자기부담금을 뺀 금액을 보상하되 복구하지 않으면 시가로 계산합니다.","농업시설물도 보험가입 당시 별도로 정한 산정 방식이 있으면 그 방법에 따른다":"농업시설물도 가입 때 별도로 정한 산정 방식이 있으면 그 방식을 따릅니다.","농업시설물은 보험가액은 재조달가액 - 감가상각액, 손해액은 원상복구비용":"농업시설물은 보험가액이 재조달가액에서 감가상각액을 뺀 값이고 손해액은 원상복구비용입니다.","농업인안전보험(농어업인의 안전보험 및 안전재해예방에 관한 법률)":"농업인안전보험은 별도 법에 따른 보험이어서 농업재해보험에 포함되지 않아요.","농업재해와 어업재해를 합한 것":"농어업재해는 농업재해와 어업재해를 합친 개념이에요.","농업정책보험금융원, 보험업법 제83조제1항에 따라 보험을 모집할 수 있는 자(모집 가능자일 뿐 위탁 대상은 아님)":"농업정책보험금융원과 단순한 보험 모집 가능자는 업무 위탁 대상에 해당하지 않습니다.","농업정책보험금융원 또는 재해보험사업자의 인터넷 홈페이지를 통해 공시":"가격 공시는 금융원이나 사업자의 인터넷 홈페이지를 통해 합니다.","농업정책보험금융원의 임원 중에서 기금수입담당임원과 기금지출원인행위담당임원을, 직원 중에서 기금지출원과 기금출납원을 각각 임명하여야 한다":"사무를 위탁하면 금융원의 임원 중에서 수입담당·지출원인행위담당을, 직원 중에서 지출원과 출납원을 임명해야 합니다.","농업협동조합법ㆍ수산업협동조합법ㆍ산림조합법에 따른 조합이 조합원에게 이 법의 보험상품 보험료 일부를 지원하는 경우는 보험업법 제98조에도 불구하고 특별이익의 제공으로 보지 않는다":"조합이 조합원에게 보험료 일부를 지원해도 보험업법상 특별이익 제공으로 보지 않습니다.","농업협동조합법에 따라 설립된 지역농업협동조합ㆍ지역축산업협동조합 및 품목별ㆍ업종별협동조합":"위탁 대상에는 지역농협·지역축협과 품목별·업종별 협동조합이 있어요.","농업협동조합법에 따른 농업협동조합중앙회":"농업협동조합중앙회는 통계 업무 위탁 대상 가운데 하나입니다.","농업협동조합중앙회는 재해보험사업을 할 수 있는 자에 들어가지 않는다, 제1호가 삭제되었다":"농업협동조합중앙회는 법 개정으로 해당 호가 삭제되어 재해보험사업자 목록에 들지 않아요.","농작물ㆍ임산물ㆍ가축 모두 보험회사 임직원 요건은 「보험ㆍ공제 관련 업무 3년 이상 또는 손해평가 업무 2년 이상」":"보험회사 임직원 요건은 세 분야 모두 보험·공제 업무 3년 이상 또는 손해평가 업무 2년 이상으로 같아요.","농작물ㆍ임산물ㆍ가축 및 농업용 시설물에 발생하는 자연재해ㆍ병충해ㆍ조수해(鳥獸害)ㆍ질병 또는 화재":"농업재해는 농작물·임산물·가축·농업용 시설물에 닥치는 자연재해, 병충해, 조수해, 질병, 화재를 가리킵니다.","농작물ㆍ임산물ㆍ가축 및 양식수산물의 재생산에 직접 소요되는 비용 보장 목적으로 입금된 보험금: 입금된 보험금 전액을 압류할 수 없다":"재생산에 직접 드는 비용을 보장하려고 입금된 보험금은 전액 압류할 수 없어요.","농작물의 보험금 산정은 별표 1, 품목별ㆍ재해별ㆍ시기별 조사방법은 별표 2, 표본주(구간) 수는 별표 2의2":"작물 보험금 산정은 별표 1, 조사방법은 별표 2, 표본주 수는 별표 2의2에 나옵니다.","농작물재해보험, 임산물재해보험, 가축재해보험":"농작물·임산물·가축재해보험이 농업재해보험에 속합니다.","농작물재해보험, 임산물재해보험, 가축재해보험, 양식수산물재해보험 4가지":"재해보험은 농작물, 임산물, 가축, 양식수산물 네 가지로 나뉩니다.","농작물재해보험ㆍ임산물재해보험ㆍ가축재해보험 관련 사항은 농림축산식품부장관이 관장, 양식수산물재해보험 관련 사항은 해양수산부장관이 관장":"앞의 세 가지는 농림축산식품부장관이, 양식수산물재해보험은 해양수산부장관이 맡아 관장합니다.","농작물재해보험 및 가축재해보험에 관한 것, 임산물재해보험의 피해사실 확인은 손해평가사 업무에 해당하지 않는다":"손해평가사는 농작물·가축재해보험 업무를 하며 임산물재해보험의 피해사실 확인은 업무에 포함되지 않아요.","농작물재해보험분과위원회, 임산물재해보험분과위원회, 가축재해보험분과위원회, 그 밖에 대통령령으로 정하는 분과위원회":"법에 정해진 분과는 농작물·임산물·가축재해보험분과위원회와 대통령령으로 정한 분과입니다.","누구든지 손해평가사의 자격을 취득하지 아니하고 그 명의를 사용하거나 자격증을 대여받아서는 아니 되며, 명의 사용이나 자격증 대여를 알선해서도 아니 된다":"자격이 없는 사람이 이름을 쓰거나 자격증을 빌리는 것, 그것을 알선하는 것도 금지됩니다.","누적피해율은 해당 보험사고로 조사된 피해율로 이전 보험사고 피해를 포함해 산출":"누적피해율은 이번 사고로 조사된 피해율에 이전 사고 피해까지 포함해 산출합니다.","늘려도 법 제32조의 상한을 넘을 수 없다":"늘리더라도 법이 정한 상한을 넘을 수 없습니다.","다: 보험업법 제4조에 따른 허가를 받은 손해보험회사":"보험업법에 따라 허가를 받은 손해보험회사도 면제 경력 기관에 포함됩니다.","다만 보험목적물이 담보로 제공된 경우에는 압류할 수 있다":"보험목적물이 담보로 잡혀 있다면 담보권 실행과 관련해 보험금 권리도 압류 대상이 됩니다.","단 10a당 식물체 주수가 30,000주보다 작고, 10a당 30,000주 이상으로 재파종한 경우에 한한다":"10a당 식물체가 30,000주보다 적고 30,000주 이상으로 다시 파종한 경우에만 지급해요.","단 면적피해율이 10%를 초과하고 재이앙(재직파)한 경우에 한한다":"면적피해율이 10%를 넘고 재이앙을 한 경우에만 지급합니다.","단 면적피해율이 자기부담비율을 초과하고 재정식ㆍ재파종한 경우에 한한다":"면적피해율이 자기부담비율을 넘고 실제 재정식·재파종을 한 경우에만 인정됩니다.","단 법 상한(1년)을 넘지 못한다":"다만 늘려도 법이 정한 상한인 1년은 넘을 수 없어요.","단 손해액이 자기부담금을 초과하는 경우에 한한다":"추가보장은 손해액이 자기부담금을 넘는 경우에만 지급해요.","단순한 차이 발생이 아니라 「현저한 차이」이고 「재조사가 불가피」할 때":"단순한 차이가 아니라 현저한 차이가 있고 재조사가 불가피한 때만 재조사가 가능해요.","단 피해율이 자기부담비율을 초과하는 경우에 한한다":"추가보장은 피해율이 자기부담비율을 넘을 때에만 지급됩니다.","대상목적물ㆍ사업지역ㆍ사업기간 / 보험상품 / 정부의 재정지원 / 그 밖에 장관이 필요하다고 인정하는 사항":"계획서에는 대상 목적물·지역·기간, 보험상품, 정부 재정지원 등이 들어갑니다.","대통령령으로 정한 그 밖의 분과위원회는 농업인안전보험분과위원회":"분과위원회의 법정 종류 외에 시행령이 더한 분과는 농업인안전보험을 맡는 위원회입니다.","동상해 과실손해조사(감귤 온주밀감류만): 사고접수 후 지체 없이, 표본주의 착과피해 조사, 12월 21일~익년 2월 말일 사고 건에 한함(표본조사)":"감귤 동상해 과실손해조사는 12월 21일부터 익년 2월 말일 사이 사고만 표본주의 착과피해를 표본조사해요.","동상해손해보험금 = 손해액 - 자기부담금":"동상해손해보험금은 손해액에서 자기부담금을 뺀 금액이에요.","동상해 피해율 = {(동상해 80%형 피해과실수 합계 × 80%) + (동상해 100%형 피해과실수 합계 × 100%)} ÷ 기준과실수":"동상해 피해율은 80%형 피해과실수에 80%, 100%형에 100%를 곱해 합한 뒤 기준과실수로 나눕니다.","동점자로 초과하면 동점자 모두 합격":"동점자 때문에 인원이 넘어가면 동점자 모두를 합격시킵니다.","동점자 점수는 소수점 이하 둘째자리까지 계산(셋째자리 이하 버림)":"동점 계산은 소수점 둘째 자리까지만 보고 셋째 자리 이하는 버립니다.","떫은감 가을동상해 → 조사내용 착과피해조사, 조사시기 수확 직전":"떫은감의 가을동상해는 착과피해조사로 수확 직전에 조사합니다.","라: 보험업법 제175조에 따라 설립된 손해보험협회":"보험업법에 따라 세운 손해보험협회도 경력을 인정하는 기관입니다.","마: 보험업법 제187조제2항에 따른 손해사정을 업으로 하는 법인":"손해사정을 업으로 하는 법인도 경력 인정 기관에 해당합니다.","마늘 재파종 비율: 35%, 20%(일반 재정식ㆍ재파종)나 25%(벼 재이앙)나 10%와 헷갈리게 나온다":"마늘 재파종은 35%이고 이는 벼 재이앙 25%나 일반 재정식 20% 등과 다른 비율입니다.","매실ㆍ대추ㆍ살구: 100주 미만 5 / 100~300 미만 7 / 300~500 미만 9 / 500~1,000 미만 12 / 1,000주 이상 16":"매실·대추·살구는 100주 미만 5주에서 1,000주 이상 16주까지 표본주를 정해요.","면적피해율 = 피해면적(㎡) ÷ 재배면적(㎡), 피해면적 = (도복(쓰러짐)으로 인한 피해면적 × 70%) + (도복 이외 피해면적 × 평균 손해정도비율)":"피해면적은 도복 피해면적의 70%에 도복 이외 피해면적에 평균 손해정도비율을 곱한 값을 더해 구합니다.","면적피해율 = 피해면적 ÷ 보험가입면적":"면적피해율은 피해면적을 보험가입면적으로 나눈 비율입니다.","면제 대상자는 제1차 시험이 면제된다":"면제 대상자는 제1차 시험을 치르지 않아도 됩니다.","모두 업무정지면 무거운 쪽의 2분의 1까지 가중할 수 있고 6개월 초과 불가":"모두 업무정지면 무거운 쪽의 2분의 1까지 가중할 수 있으나 6개월을 넘을 수 없어요.","모집 업무 종사자가 사용하는 안내자료 및 금지행위는 보험업법 제95조ㆍ제97조ㆍ제98조 및 금융소비자 보호에 관한 법률 제21조를 준용":"모집 종사자의 안내자료와 금지행위는 보험업법과 금융소비자 보호법 규정을 준용합니다.","목적의 끝: 농어업 경영의 안정과 생산성 향상에 이바지하고 국민경제의 균형 있는 발전에 기여":"궁극 목적은 농어업 경영이 안정되고 생산성이 높아져 국민경제가 균형 있게 발전하도록 돕는 것이에요.","민법 제32조에 따라 장관의 허가를 받아 설립된 비영리법인":"민법에 따라 장관 허가를 받아 설립된 비영리법인도 대상이에요.","바: 화재로 인한 재해보상과 보험가입에 관한 법률 제11조에 따라 설립된 한국화재보험협회":"한국화재보험협회도 경력 인정 기관으로 열거돼 있어요.","반원 1: 손해평가인, 반원 2: 손해평가사":"손해평가인과 손해평가사가 평가반 구성원이 될 수 있어요.","반원 3: 보험업법 제186조에 따른 손해사정사":"보험업법상 손해사정사도 반원이 될 수 있습니다.","발생 빈도, 피해 정도 및 객관적인 손해평가방법 등을 고려하여 재해보험의 종류별로 대통령령으로 정한다":"보상하는 재해는 발생 빈도와 피해 정도, 객관적인 평가 방법을 따져 대통령령으로 종류별로 정합니다.","방풍림, 돌담, 도로(농로 제외) 등에 의해 구획된 것 또는 동일한 울타리, 시설 등에 의해 구획된 것을 하나의 농지로 한다":"방풍림, 돌담, 도로, 같은 울타리·시설로 구획된 땅을 하나의 농지로 봅니다.","배제 4호는 ‘자기가 실시한’ 손해평가에 한한다":"배제 4호는 자기 자신이 실시한 평가에만 적용됩니다.","배추(고랭지배추), 파, 무(고랭지무, 가을무(단무지무, 알타리무)), 시금치, 양상추, 메밀: 보험가입금액 × (피해율 - 자기부담비율)":"배추·파·무·시금치·양상추·메밀의 생산비보장은 가입금액에 피해율과 자기부담비율의 차를 곱합니다.","법 및 요령에 의한 명령이나 처분을 위반한 때: 1차 업무정지 6개월, 2차 위촉해지":"명령·처분 위반은 업무정지 6개월 다음에 위촉해지로 이어집니다.","법 시행령상 실무교육 내용: 보험에 관한 기초지식, 보험약관 및 손해평가요령 등, 실시 주체는 재해보험사업자":"실무교육은 보험 기초지식과 약관, 평가요령 등을 다루며 실시 주체는 사업자예요.","법인의 대표자나 대리인, 사용인, 종업원이 업무에 관하여 제30조 위반행위를 하면 행위자를 벌하는 외에 법인 또는 개인에게도 해당 조문의 벌금형을 과한다":"법인의 직원이 업무에 관해 위반하면 행위자를 벌하는 것 외에 법인에도 벌금형을 과합니다.","법 제11조의4제1항에 따른 자격시험에 합격한 자":"손해평가사는 법에 따른 자격시험에 합격한 사람입니다.","법 제11조제1항과 시행령 제12조제1항에서 정한 자 중에서 재해보험사업자가 위촉하여 손해평가업무를 담당하는 자":"손해평가인은 재해보험사업자가 위촉해 손해평가 업무를 맡기는 사람입니다.","법 제2조제1호에 따른 피해가 발생한 경우 법 제11조 및 제11조의3에 따라 손해평가인, 손해평가사 또는 손해사정사가 피해사실을 확인하고 평가하는 일련의 과정":"손해평가는 평가인·평가사·사정사가 피해사실을 확인하고 평가하는 일련의 과정이에요.","법 제30조가 아닌 도로교통법 등 다른 법률 위반 벌금형":"도로교통법 같은 다른 법률 위반 벌금형은 위촉 취소 사유가 아닙니다.","법 제4조에 따른 농작물재해보험, 임산물재해보험 및 가축재해보험":"농업재해보험은 농작물재해보험, 임산물재해보험, 가축재해보험을 말합니다.","벼, 밀, 보리, 귀리: 조사대상면적 2,000㎡ 미만 3 / 2,000~3,000 미만 4 / 3,000~4,000 미만 5 / 4,000~5,000 미만 6 / 5,000~6,000 미만 7 / 6,000㎡ 이상 8":"벼·밀·보리·귀리는 조사대상면적이 2,000㎡ 미만이면 3구간, 6,000㎡ 이상이면 8구간을 조사합니다.","병충해 및 질병 손해평가: 재해보험사업자는 「농업재해보험 보험목적물별 보상하는 병충해 및 질병규정」의 병충해ㆍ질병 피해 평가를 위해 해당 분야 전문지식을 갖춘 자에게 조사를 의뢰하거나 자문을 요청할 수 있다":"병충해와 질병 피해 평가가 필요하면 사업자는 전문지식을 갖춘 자에게 조사를 의뢰하거나 자문을 구할 수 있습니다.","병충해와 조수해는 어업재해에 들어가지 않는다":"병충해와 조수해는 농업재해에만 있는 항목이어서 어업재해의 범위에서는 빠집니다.","보상하는 재해 전부, 사고접수 후 지체 없이, 피해발생 여부 조사, 피해사실이 명백한 경우 생략 가능":"수확 전 피해사실확인조사는 피해 발생 여부를 조사하며 피해가 명백하면 생략할 수 있어요.","보험가액이 보험가입금액보다 적을 경우에는 보험가액에 의하며, 기타 세부 내용은 재해보험사업자가 작성한 손해평가 업무방법서에 따른다":"보험가액이 가입금액보다 적으면 보험가액을 기준으로 하고 나머지는 업무방법서를 따릅니다.","보험가액이 보험가입금액보다 커도 보험가입금액 기준, 보험가액이 가입금액보다 적을 때만 보험가액에 의한다":"보험가액이 가입금액보다 커도 가입금액이 기준이고, 가액이 더 작을 때만 보험가액을 따릅니다.","보험가입금액 1,000만원, 피해주수 100, 실제결과주수 200, 자기부담비율 10% → 피해율 50%, 1,000만원 × (0.5 - 0.1) = 400만원":"피해율 50%에서 자기부담 10%를 뺀 비율을 1,000만원에 곱해 400만원이 됩니다.","보험가입금액 100만원 × (0.45 - 0.2) = 25만원":"가입금액 100만원에 피해율 0.45에서 0.2를 뺀 값을 곱해 25만원이 됩니다.","보험가입금액 × (피해율 - 자기부담비율)":"인삼 보험금은 가입금액에 피해율에서 자기부담비율을 뺀 값을 곱해 구합니다.","보험가입금액 × (피해율 - 자기부담비율), 피해율 = 피해주수(고사된 나무) ÷ 실제결과주수":"종합위험 나무손해는 가입금액에 피해율과 자기부담비율의 차를 곱하며, 피해율은 고사 나무 수를 실제결과주수로 나눠 구해요.","보험가입금액 × (피해율 × 10%)":"수확량감소 추가보장은 가입금액에 피해율의 10%를 곱한 금액이에요.","보험가입금액 × 20% × 면적피해율":"마늘·당근 외 작물의 재정식·재파종 보험금은 가입금액의 20%에 면적피해율을 곱해요.","보험가입금액 × 25% × 면적피해율":"재이앙·재직파 보험금은 가입금액의 25%에 면적피해율을 곱한 금액이에요.","보험가입금액 × 35% × 표준피해율":"마늘 남도·대서 재파종은 가입금액의 35%에 표준피해율을 곱한 금액입니다.","보험가입금액 × [누적피해율 - 기누적피해율] - 자기부담금":"고추 생산비보장 보험금은 가입금액에 누적피해율과 기누적피해율의 차를 곱하고 자기부담금을 뺀 값이에요.","보험가입금액 × 보장비율 × 경과비율":"사료용 옥수수·조사료용 벼의 경작불능 보험금은 가입금액에 보장비율과 경과비율을 곱해 구해요.","보험가입금액 × 주계약피해율 × 10%":"감귤 과실손해 추가보장은 가입금액에 주계약피해율과 10%를 곱한 금액입니다.","보험가입금액이 보험가액과 같거나 클 때: 보험가입금액을 한도로 손해액에서 자기부담금을 차감한 금액":"해가림시설은 가입금액이 가액 이상이면 가입금액을 한도로 손해액에서 자기부담금을 뺀 금액을 줍니다.","보험가입금액이 보험가액보다 작을 때: (손해액 - 자기부담금) × (보험가입금액 ÷ 보험가액)":"가입금액이 보험가액보다 작으면 손해액에서 자기부담금을 뺀 값에 가입금액 대 보험가액 비율을 곱합니다.","보험가입 당시 보험가입자와 재해보험사업자가 보험가액 및 손해액 산정 방식을 별도로 정한 경우에는 그 방법에 따른다":"가입 당시 가입자와 사업자가 산정 방식을 따로 정했다면 그 방법에 따릅니다.","보험가입자가 보험책임기간 중에 피해발생 통지를 한 때 재해보험사업자는 손해평가반으로 하여금 지체 없이 피해사실을 확인하고 손해평가를 실시하게 하여야 한다":"가입자가 보험책임기간에 피해를 통지하면 사업자는 평가반이 곧바로 피해사실을 확인하게 해야 합니다.","보험가입자가 설명 또는 통지를 받은 날부터 7일 이내에 손해평가가 잘못되었음을 증빙하는 서류 또는 사진 등을 제출하면, 재해보험사업자는 다른 손해평가반으로 하여금 재평가를 실시하게 할 수 있다":"가입자가 통지받은 날부터 7일 안에 잘못을 증빙하는 자료를 내면 다른 평가반이 재평가할 수 있어요.","보험가입자가 정당한 사유 없이 검증조사를 거부하면 검증조사반은 검증조사가 불가능하여 손해평가 결과를 확인할 수 없다는 사실을 보험가입자에게 통지한 후 검증조사결과를 작성하여 재해보험사업자에게 제출한다":"가입자가 검증조사를 거부하면 확인이 불가능하다고 가입자에게 통지한 뒤 결과를 작성해 사업자에게 냅니다.","보험가입자가 정당한 사유 없이 서명을 거부하면 손해평가 결과를 통지한 후 서명 없이 현지조사서를 제출한다":"가입자가 정당한 이유 없이 서명을 거부하면 결과를 통지한 뒤 서명 없이 제출합니다.","보험가입자가 정당한 사유 없이 손해평가를 거부하여 실시하지 못한 경우: 그 피해를 인정할 수 없는 것으로 평가한다는 사실을 보험가입자에게 통지한 후 현지조사서를 재해보험사업자에게 제출한다":"정당한 이유 없이 평가를 거부해 실시하지 못하면 피해를 인정하지 않는다고 통지한 뒤 현지조사서를 냅니다.","보험가입자는 당초 손해평가를 담당하였던 손해평가인ㆍ손해평가사ㆍ손해사정사의 교체를 요구할 수 있고, 사업자는 특별한 사정이 없으면 따라야 한다":"가입자는 처음 평가한 사람을 바꿔 달라고도 요구할 수 있으며 사업자는 특별한 사정이 없으면 따릅니다.","보험가입자는 재평가를 요청할 수 있고, 당초 평가인의 교체를 요구할 수 있다":"가입자는 재평가를 요청할 수 있고 처음 평가한 평가인을 바꿔 달라고도 요구할 수 있습니다.","보험가입자는 재해로 인한 사고의 예방을 위하여 노력하여야 한다":"보험가입자도 재해로 인한 사고를 막기 위해 노력해야 합니다.","보험가입자의 재산 피해에 따른 손해가 발생한 경우 보험에서 최대로 보상할 수 있는 한도액으로서 보험가입자와 보험사업자 간에 약정한 금액":"보험가입금액은 약정으로 정한, 사고가 났을 때 보험이 보상해 줄 수 있는 최대 한도입니다.","보험계약자 또는 보험사업자로부터 금품ㆍ향응을 제공받은 경우 — 6개월/1년/1년":"금품·향응을 받은 경우도 6개월, 1년, 1년으로 같은 단계로 정지됩니다.","보험금: 보험가입자에게 재해로 인한 재산 피해에 따른 손해가 발생한 경우 보험가입자와 보험사업자 간의 약정에 따라 보험사업자가 보험가입자에게 지급하는 금액":"보험금은 재해 피해가 났을 때 약정에 따라 사업자가 가입자에게 주는 돈입니다.","보험금수급전용계좌 예금 중 대통령령으로 정하는 액수 이하의 금액에 관한 채권은 압류할 수 없다":"전용계좌 예금 중 대통령령이 정한 금액 이하의 채권은 압류가 금지됩니다.","보험금수급전용계좌의 해당 금융기관은 이 법에 따른 보험금만이 그 계좌에 입금되도록 관리하여야 한다":"금융기관은 이 법에 따른 보험금만 전용계좌에 들어오도록 관리해야 합니다.","보험금은 사업자가 주는 돈, 둘이 바뀐 문장이 오답으로 나온다":"보험료와 보험금은 돈이 오가는 방향이 반대이므로 주체를 바꿔 쓰면 틀린 설명이 됩니다.","보험금 지급청구서에 수급권자 명의 계좌를 기재하고 통장 사본(계좌번호가 기재된 면)을 첨부하여 재해보험사업자에게 제출":"지급청구서에 수급권자 명의 계좌를 적고 통장 사본을 붙여 사업자에게 내면 됩니다.","보험기간 내, 보상하는 재해 전부: 해가림시설조사(인삼), 비가림시설조사, 시설조사(원예시설, 버섯재배사) — 사고접수 후 지체 없이, 전수조사":"해가림·비가림·원예시설 조사는 사고접수 후 지체 없이 전수조사로 합니다.","보험기간 중 태풍(강풍)ㆍ폭설ㆍ집중호우ㆍ침수ㆍ화재ㆍ우박ㆍ냉해ㆍ폭염: 수확량 조사 — 조사시기 「피해 확인이 가능한 시기」, 방법: 전수조사 또는 표본조사":"특정위험방식 인삼은 태풍·폭설·집중호우 등 사고에 대해 수확량을 조사하며, 시기는 피해 확인이 가능한 때입니다.","보험료: 보험가입자와 보험사업자 간의 약정에 따라 보험가입자가 보험사업자에게 내야 하는 금액":"보험료는 약정에 따라 가입자가 사업자에게 내는 돈입니다.","보험료는 일부만 지원, 전부 지원이 아니다":"정부가 지원하는 것은 보험료 중 일부이고 전부를 대 주지는 않아요.","보험료를 추가 지원하려는 경우 재해보험 가입현황서와 보험가입자의 기준 등을 확인하여 보험료의 지원금액을 결정ㆍ지급":"지자체장도 추가 지원할 때 가입현황서와 가입자 기준을 확인해 금액을 정해 지급해요.","보험료와 운영비의 지원 방법 및 지원 절차 등은 대통령령으로 정한다":"보험료와 운영비의 지원 방법과 절차는 대통령령에서 정합니다.","보험료율 산정, 재해보험사업의 약정 체결, 재해보험상품의 연구와 보급":"보험료율 산정, 약정 체결, 상품 연구와 보급은 손해평가인의 업무가 아닙니다.","보험목적물 또는 관련 분야에 관한 전문 지식과 경험을 갖춘 대통령령 기준의 사람에게는 시험 과목의 일부를 면제할 수 있다":"전문 지식과 경험을 갖춘 사람에게는 시험 과목의 일부를 면제해 줄 수 있어요.","보험사고가 발생한 때와 곳에서 산정한 피해목적물의 원상복구비용":"손해액은 사고가 난 때와 곳에서 계산한 피해목적물의 원상복구비용입니다.","보험사고가 발생한 때와 곳에서 평가한 보험목적물의 수량 × 적용가격":"가축의 보험가액은 사고 때 그 장소에서 평가한 수량에 적용가격을 곱해 구합니다.","보험사고가 발생한 때와 곳에서 평가한 피해목적물의 재조달가액 - 내용연수에 따른 감가상각률을 적용하여 계산한 감가상각액":"농업시설물 보험가액은 재조달가액에서 내용연수에 따라 계산한 감가상각액을 뺀 금액입니다.","보험사고가 발생한 때와 곳에서 폐사 등 피해를 입은 보험목적물의 수량 × 적용가격":"가축 손해액은 사고 때 그 장소에서 폐사 등 피해를 입은 수량에 적용가격을 곱한 값입니다.","보험상품에 적용하는 가격은 장관이 공시할 수 있다":"장관은 보험상품에 적용하는 가격을 공시할 수 있어요.","보험안내 위반(사업자) 1천만 / 보험안내 위반(비사업자) 500만 / 금지행위 위반 300만 / 보고ㆍ서류제출 위반 300만 / 책임준비금 미계상 500만 / 명령 위반 300만 / 검사 거부 200만":"과태료는 보험안내 위반 사업자 1천만, 비사업자 500만, 금지행위·보고 위반 300만, 검사 거부 200만 등으로 갈립니다.","보험업법에 따른 보험회사, 보험료율산출기관 또는 보험계리를 업으로 하는 자":"보험회사, 보험료율산출기관, 보험계리를 업으로 하는 자도 위탁 대상입니다.","보험업법 제129조의 보험료율 산출 원칙에 부합하면 자치구가 아닌 구ㆍ읍ㆍ면ㆍ동 단위로도 산정할 수 있다":"보험업법의 보험료율 산출 원칙에 맞으면 구·읍·면·동 단위로도 산정할 수 있어요.","보험업법 제131조제1항ㆍ제2항 및 제4항에 따른 명령을 위반한 경우":"보험업법상 명령을 어기면 과태료가 부과되는 사유가 됩니다.","보험업법 제133조에 따른 검사를 거부ㆍ방해 또는 기피한 경우":"금융당국의 검사를 거부·방해·기피한 경우도 과태료 대상입니다.","보험업법 제186조에 따른 손해사정사":"보험업법상 손해사정사로 인정받은 사람은 첫 단계 시험을 치르지 않아도 됩니다.","보험업법 제83조제1항에 따라 보험을 모집할 수 있는 자":"보험업법에 따라 보험을 모집할 수 있는 자도 재해보험 모집이 가능합니다.","보험업법 제97조제1항 또는 금융소비자 보호에 관한 법률 제21조를 위반하여 보험계약의 체결 또는 모집에 관한 금지행위를 한 자":"보험 체결·모집의 금지행위를 한 사람에게도 과태료가 부과됩니다.","보험업법 제98조에 따른 금품 등을 제공(같은 조 제3호의 경우에는 보험금 지급의 약속)한 자, 또는 이를 요구하여 받은 보험가입자":"금품을 제공했거나 요구해 받은 가입자는 3년 이하 징역 또는 3천만원 이하 벌금 대상입니다.","보험증권에 기재된 보험목적물의 평년수확량에 보험가입 당시의 단위당 가입가격을 곱하여 산정":"종합위험방식은 증권에 적힌 평년수확량에 단위당 가입가격을 곱해 보험가액을 산정합니다.","보험증권이나 주민등록증이 아니다":"제시할 서류는 보험증권이나 주민등록증이 아니라 평가인증 등 신분 확인 서류입니다.","보험회사의 임직원이나 농업협동조합법에 따른 중앙회와 조합의 임직원으로 영농 지원 또는 보험ㆍ공제 관련 업무를 3년 이상 담당하였거나 손해평가 업무를 2년 이상 담당한 경력":"보험회사나 농협 임직원이 보험·공제 업무 3년 이상 또는 손해평가 업무 2년 이상 맡았다면 자격이 있어요.","복분자(가입포기수): 1,000포기 미만 8 / 1,000~1,500 미만 9 / 1,500~2,000 미만 10 / 2,000~2,500 미만 11 / 2,500~3,000 미만 12 / 3,000포기 이상 13":"복분자는 가입포기수가 1,000포기 미만이면 8포기, 3,000포기 이상이면 13포기를 조사해요.","복분자: 수정완료 후, 살아있는 결과모지수 조사 및 수정불량(송이)피해율 조사(표본조사)":"복분자 과실손해조사는 수정 완료 후 살아 있는 결과모지 수와 수정불량 피해율을 표본조사합니다.","복분자 피해율 = 고사결과모지수 ÷ 평년결과모지수, 계산식이 「고사결과모지수 ÷ 평년결과모지수」인 품목은 복분자":"복분자 피해율은 고사한 결과모지 수를 평년 결과모지 수로 나눈 값입니다.","부위원장은 위원장을 보좌하며, 위원장이 부득이한 사유로 직무를 수행할 수 없을 때 그 직무를 대행":"부위원장은 위원장을 돕고, 위원장이 부득이하면 그 직무를 대신합니다.","부위원장은 위원 중에서 호선(互選)":"부위원장은 위원들이 서로 뽑는 호선으로 정합니다.","부정한 방법으로 시험에 응시한 사람, 시험에서 부정한 행위를 한 사람에 대하여는 시험을 정지시키거나 무효로 하고 그 처분 사실을 지체 없이 알려야 한다, 일수 제한은 없다":"부정한 방법으로 응시한 사람의 시험은 정지시키거나 무효로 하며 처분 사실을 지체 없이 알립니다.","분과위원장 1명을 포함한 9명 이내의 분과위원으로 성별을 고려하여 구성":"분과위원은 분과위원장 포함 9명 이내로, 성별을 고려해 구성해요.","분과위원장 및 분과위원은 심의회 위원 중에서 전문적인 지식과 경험 등을 고려하여 위원장이 지명":"분과위원은 심의회 위원 가운데서 뽑으며, 전문성을 보고 위원장이 직접 지명하는 방식이에요.","분과위원회는 맡은 심의사항을 검토ㆍ조정하여 심의회에 보고":"분과위원회는 맡은 사항을 검토·조정한 뒤 그 결과를 심의회에 보고합니다.","분과위원회 회의는 위원장 또는 분과위원장이 필요하다고 인정할 때 소집":"분과위원회는 위원장이나 분과위원장 중 누구든 필요하다고 보면 회의를 열 수 있습니다.","불가피한 사유: 계좌가 개설된 금융기관의 폐업ㆍ업무 정지 등으로 정상영업이 불가능한 경우":"계좌 개설 금융기관이 폐업하거나 업무정지로 정상 영업이 불가능한 경우가 불가피한 사유입니다.","사고접수 후 지체 없이, 보상하는 손해로 재이앙(재직파)이 필요한 면적 또는 면적비율 조사, 벼만 해당":"재이앙조사는 재이앙이 필요한 면적 또는 비율을 조사하며 벼만 해당합니다.","사고접수 후 지체 없이, 재정식이 필요한 면적 또는 면적비율 조사, 양배추(가을양배추, 월동양배추), 단호박, 배추(봄배추, 가을배추, 월동배추), 양파만 해당, 벼ㆍ콩은 재정식 조사 대상이 아니다":"재정식조사는 양배추, 단호박, 배추, 양파 등만 대상이고 벼와 콩은 해당하지 않습니다.","사고접수 후 지체 없이, 재파종이 필요한 면적 또는 면적비율 조사, 마늘(남도, 대서), 가을감자, 무(봄무, 가을무(일반무), 월동무), 당근(고랭지당근, 가을ㆍ월동당근)만 해당":"재파종조사는 마늘, 가을감자, 무, 당근 등 지정 품목만 대상이에요.","사고접수 후 지체 없이, 해당 농지의 피해면적비율 또는 보험목적인 식물체 피해율 조사, 벼ㆍ밀, 밭작물(차(茶) 제외), 복분자만 해당":"경작불능조사는 피해면적비율이나 식물체 피해율을 조사하며 벼·밀·밭작물·복분자에 해당합니다.","사고접수 후 지체 없이: 피해사실확인조사, 낙과피해조사, 재이앙ㆍ재파종ㆍ재정식ㆍ경작불능조사, 시설 조사":"사고접수 후 지체 없이 하는 조사에는 피해사실확인·낙과피해·재이앙 등·시설 조사가 있어요.","사과, 배, 단감, 떫은감, 포도, 복숭아, 자두, 밤, 호두, 무화과, 감귤(만감류): 조사대상주수 50주 미만 5 / 50~100 미만 6 / 100~150 미만 7 / 150~200 미만 8 / 200~300 미만 9 / 300~400 미만 10 / 400~500 미만 11 / 500~600 미만 12 / 600~700 미만 13 / 700~800 미만 14 / 800~900 미만 15 / 900~1,000 미만 16 / 1,000주 이상 17":"과수류 표본주 수는 조사대상주수가 많을수록 늘어나 50주 미만 5주에서 1,000주 이상 17주까지입니다.","사업 관리 위탁 기관이 검증조사를 실시한 경우 그 결과를 재해보험사업자에게 통보하고 필요에 따라 결과에 대한 조치를 요구할 수 있다":"위탁 기관이 검증조사를 했다면 결과를 사업자에게 알리고 필요하면 조치를 요구할 수 있습니다.","산림조합법 제48조의 공제규정에 따른 공제모집인으로서 산림조합중앙회장이나 그 회원조합장이 인정하는 자":"산림조합법상 공제모집인은 중앙회장이나 조합장이 인정한 사람일 때 보험 모집이 가능합니다.","산림조합중앙회와 그 회원조합의 임직원, 수협중앙회와 그 회원조합 및 수협은행의 임직원":"모집 가능자에는 산림조합중앙회와 수협중앙회 계통의 임직원이 포함됩니다.","상당한 주의와 감독을 게을리하지 않은 경우는 제외":"법인이 상당한 주의와 감독을 게을리하지 않았다면 법인에는 벌금을 과하지 않아요.","새마을금고중앙회, 은행(은행법)은 재해보험사업을 할 수 없다":"새마을금고중앙회와 은행은 재해보험사업을 할 수 없는 기관이에요.","생계를 같이 하지 않는 친족은 해당하지 않는다":"생계를 따로 하는 친족은 이해관계자에 해당하지 않아요.","생산비보장에서 병충해 등급별 인정비율을 확인하는 품목은 고추(노지), 무ㆍ파ㆍ배추가 아니다":"병충해 등급별 인정비율을 확인하는 품목은 노지 고추이며 무·파·배추는 아닙니다.","생산비 피해조사(수확 직전): 사고발생 농지의 피해비율 및 손해정도 비율 확인을 통한 피해율 조사(표본조사)":"생산비 피해조사는 수확 직전 피해비율과 손해정도 비율로 피해율을 표본조사하는 것이에요.","선발예정인원을 공고한 경우(제2차 시험): 매 과목 40점 이상인 사람 중 전 과목 총득점이 높은 사람부터 선발예정인원까지":"선발예정인원이 있으면 과목당 40점 이상 중 총득점이 높은 사람부터 그 인원까지 뽑아요.","선정한 시ㆍ군ㆍ구 내에서 손해평가 경력, 타지역 조사 가능여부 등을 고려하여 교차손해평가를 담당할 지역손해평가인을 선발하여야 한다":"다음으로 평가 경력과 타지역 조사 가능 여부를 보고 담당 지역손해평가인을 선발합니다.","세부기준은 농림축산식품부장관과 해양수산부장관이 정하여 고시":"세부 기준은 두 장관이 정해 고시합니다.","손해액 = {보험가입금액 - (보험가입금액 × 기사고 피해율)} × 수확기 잔존비율 × 동상해피해율 × (1 - 미보상비율)":"동상해 손해액은 기사고 피해율을 빼고 남은 가입금액에 수확기 잔존비율과 동상해피해율, 미보상 반영분을 곱해 구합니다.","손해액 = 피해수확량 × 가입가격":"옥수수 손해액은 피해수확량에 가입가격을 곱해 구해요.","손해액의 시점은 「손해액을 평가하는 때」가 아니라 「보험사고가 발생한 때와 곳」":"손해액의 기준 시점은 평가하는 때가 아니라 보험사고가 발생한 때와 곳이에요.","손해평가 결과에 이의가 있는 보험가입자는 재해보험사업자에게 재평가를 요청할 수 있다, 사업자는 특별한 사정이 없으면 따라야 한다":"평가 결과에 이의가 있는 가입자는 재평가를 요청할 수 있고 사업자는 특별한 사정이 없으면 따라야 합니다.","손해평가 관련 민원사례, 농업재해보험상품의 개선ㆍ개발계획":"손해평가 관련 민원사례와 상품 개선·개발계획은 정기교육 세부내용에 들어 있지 않아요.","손해평가는 공정하고 객관적으로 하여야 하며, 고의로 진실을 숨기거나 거짓으로 손해평가를 하여서는 아니 된다":"손해평가는 공정하고 객관적이어야 하며 일부러 진실을 숨기거나 거짓으로 해서는 안 됩니다.","손해평가를 실시하기 전에 현지조사서를 손해평가반에게 배부하고 주의사항을 숙지시킨 후 평가에 임하도록 한다, 배부 주체도 재해보험사업자":"평가 전 현지조사서를 배부하고 주의사항을 숙지시키는 주체도 사업자예요.","손해평가반은 아래 어느 하나에 해당하는 자로 구성하며 5인 이내로 한다":"평가반은 정해진 자격자 중에서 5인 이내로 꾸립니다.","손해평가반은 조사결과 1부를 재해보험사업자에게 제출":"평가반은 생육상황 조사결과를 한 부 사업자에게 제출합니다.","손해평가반은 현지조사서에 결과를 정확하게 작성하여 보험가입자에게 설명한 후 서명을 받아 최종 조사일로부터 7영업일 이내에 재해보험사업자에게 제출한다":"평가반은 결과를 정확히 적어 가입자에게 설명하고 서명을 받아 최종 조사일부터 7영업일 안에 사업자에게 냅니다.","손해평가반을 구성하고 손해평가반별로 평가일정계획을 수립하여야 한다":"사업자는 평가반을 구성하고 반별로 평가일정계획을 세워야 해요.","손해평가반이 손해평가를 실시할 때에는 재해보험사업자가 보험가입자의 보험계약사항 중 손해평가와 관련된 사항을 손해평가반에게 통보하여야 한다":"평가반이 평가할 때 사업자는 평가에 관련된 계약사항을 평가반에 알려 주어야 해요.","손해평가반이 장관에게 검증조사를 하게 하는 구조가 아니다, 지시 주체는 장관, 대상은 재해보험사업자":"지시하는 쪽은 장관이고 받는 쪽은 사업자이며 평가반이 장관에게 시키는 구조가 아닙니다.","손해평가보조인, 공인회계사는 현행 요령상 반원이 될 수 없다":"평가반원이 될 수 있는 자격자 목록에는 보조인과 공인회계사가 들어 있지 않습니다.","손해평가사가 되려는 사람은 농림축산식품부장관이 실시하는 손해평가사 자격시험에 합격하여야 한다":"손해평가사가 되려면 농림축산식품부장관이 실시하는 자격시험에 합격해야 해요.","손해평가사는 다른 사람에게 명의를 사용하게 하거나 자격증을 대여해서는 아니 된다":"손해평가사는 남에게 자기 이름을 쓰게 하거나 자격증을 빌려줘서는 안 됩니다.","손해평가사 또는 보험업법 제186조에 따른 손해사정사에게 손해평가를 담당하게 할 수도 있다":"손해평가사나 보험업법상 손해사정사에게도 손해평가를 맡길 수 있어요.","손해평가사 자격시험의 실시 및 관리 업무는 농업정책보험금융원이 아니라 한국산업인력공단에 위탁할 수 있다(농림축산식품부장관)":"손해평가사 자격시험의 실시·관리는 금융원이 아니라 한국산업인력공단에 위탁할 수 있습니다.","손해평가 업무를 보조하는 자":"손해평가보조인은 평가를 거드는 보조 역할이고 평가 판단 자체를 맡는 사람이 아닙니다.","손해평가 요령을 고시하려면 미리 금융위원회와 협의하여야 한다, 인가가 아니다":"손해평가 요령을 고시하려면 미리 금융위원회와 협의해야 하며 인가를 받는 것은 아닙니다.","손해평가 요령을 준수하지 않고 손해평가를 한 경우 — 경고/1개월/3개월":"요령을 지키지 않고 평가하면 경고, 1개월, 3개월의 순서로 처분합니다.","손해평가인ㆍ손해평가사ㆍ손해사정사는 농림축산식품부장관 또는 해양수산부장관이 고시하는 손해평가 요령에 따라 손해평가를 하여야 한다":"손해평가는 장관이 고시한 손해평가 요령에 따라 해야 합니다.","손해평가인ㆍ손해평가사ㆍ손해사정사는 임무 수행 전에 보험가입자(피보험자 포함)에게 손해평가인증, 손해평가사자격증, 손해사정사등록증 등 신분을 확인할 수 있는 서류를 제시하여야 한다":"임무를 시작하기 전에 평가인증이나 자격증 같은 신분 확인 서류를 가입자에게 보여야 해요.","손해평가인 상호간에 담당지역을 교차하여 평가하는 것":"교차손해평가는 평가인끼리 담당 지역을 서로 바꿔 평가하는 방식입니다.","손해평가인으로 위촉된 기간이 3년 이상인 사람으로서 손해평가 업무를 수행한 경력이 있는 사람":"손해평가인으로 3년 이상 위촉되어 평가를 해 본 사람은 첫 단계 시험을 면제받습니다.","손해평가인의 정기교육에 관한 사항은 기본계획 포함사항으로 명시되어 있지 않다":"손해평가인의 정기교육은 기본계획에 담기는 사항으로 명시되어 있지 않아요.","수산업협동조합법에 따라 설립된 지구별 수산업협동조합, 업종별 수산업협동조합, 수산물가공 수산업협동조합 및 수협은행":"지구별 수협, 업종별 수협, 수산물가공 수협과 수협은행도 위탁받을 수 있어요.","수산업협동조합법에 따른 수산업협동조합중앙회 및 수협은행":"수산업협동조합중앙회와 수협은행도 통계 업무 위탁 대상입니다.","수산업협동조합법 제60조의 공제규약에 따른 공제모집인으로서 수협중앙회장 또는 그 회원조합장이 인정하는 자":"수산업협동조합법의 공제규약에 따른 공제모집인으로서 수협중앙회장이나 조합장이 인정한 자도 모집할 수 있습니다.","수시조사는 기본계획 및 시행계획을 효과적으로 수립ㆍ시행하기 위하여 필요하다고 인정하는 경우 실시":"수시조사는 계획을 잘 수립하고 시행하려고 필요하다고 판단될 때 하는 조사입니다.","수협중앙회(수산업협동조합법), 산림조합중앙회(산림조합법), 보험회사(보험업법)":"재해보험사업을 할 수 있는 자는 수협중앙회, 산림조합중앙회, 보험회사입니다.","수확감소보장 보험금 = 보험가입금액 × (피해율 - 자기부담비율), 옥수수는 따로 계산":"수확감소보장은 가입금액에 피해율에서 자기부담비율을 뺀 값을 곱하며 옥수수는 따로 계산합니다.","수확량조사(차(茶)만 해당): 조사 가능일, 사고발생 농지의 수확량조사(표본조사)":"차(茶)의 수확량조사는 조사 가능일에 사고 농지의 수확량을 표본조사해요.","수확량 조사: 보상하는 재해 전부, 수확 직전, 사고발생 농지의 수확량 조사, 전수조사 또는 표본조사":"수확량조사는 수확 직전에 사고 농지의 수확량을 전수 또는 표본조사하는 것이에요.","수확불능확인조사(벼만): 조사 가능일, 사고발생 농지의 제현율 및 정상 출하 불가 확인 조사, 전수조사 또는 표본조사":"벼의 수확불능확인조사는 제현율과 정상 출하 불가 여부를 조사하는 것이에요.","수확 전 피해사실확인조사: 사고접수 후 지체 없이, 메밀, 고추, 시금치, 양상추, 배추(고랭지배추), 파, 무(고랭지무, 가을무(단무지무, 알타리무)), 브로콜리, 노지오이만 해당, 피해사실이 명백하면 생략 가능":"수확 전 피해사실확인조사는 메밀, 고추, 시금치 등 지정 품목만 대상이며 피해가 명백하면 생략할 수 있어요.","수확 중 수확량조사: 사고접수 후 지체 없이, 수확 중의 수확량 및 감수량 확인을 통한 수확량 조사, 전수조사 또는 표본조사":"수확 중 수확량조사는 수확 도중의 수확량과 감수량을 확인해 전수 또는 표본조사합니다.","수확 직전: 착과수조사, 수확량조사, 과실손해조사, 착과피해조사, 생산비 피해조사":"수확 직전에 하는 조사에는 착과수·수확량·과실손해·착과피해·생산비 피해조사가 있습니다.","숫자 3과 2의 위치를 바꾼 선지가 나온다":"보험·공제 업무가 3년, 손해평가 업무가 2년이라는 짝이 바뀌면 틀린 요건이 됩니다.","승계한다고 단정하는 것이 아니라 추정":"승계를 단정하는 것이 아니라 추정한다는 점에서 반증의 여지가 있어요.","시범사업을 하려면 사업계획서를 장관에게 제출하고 협의하여야 한다":"시범사업을 하려면 사업계획서를 장관에게 내고 협의해야 해요.","시범사업이 끝나면 지체 없이 사업결과보고서를 제출하여야 한다":"시범사업이 끝나면 곧바로 사업결과보고서를 내야 합니다.","시설작물: 피해작물재배면적 × 단위면적당 보장생산비 × 경과비율 × 피해율, 피해율 = 피해비율 × 손해정도비율 × (1 - 미보상비율), 장미, 부추, 시금치, 파, 무, 쑥갓, 버섯은 별도로 구분하여 산출":"시설작물은 피해 재배면적, 보장생산비, 경과비율, 피해율을 곱하며 일부 작물은 따로 산출합니다.","시설작물ㆍ버섯: 단동 하우스는 전수조사, 연동 하우스는 피해가 발생한 하우스 연동 수로 표본(주) 구간 수를 정한다":"시설작물과 버섯은 단동 하우스는 전수조사하고 연동 하우스는 피해 연동 수로 표본구간 수를 정합니다.","시험 실시 90일 전까지 인터넷 홈페이지 등에 공고":"시험 공고는 시험일을 기준으로 90일 앞선 시점까지 홈페이지 등에 내야 합니다.","시험은 제1차 시험과 제2차 시험으로 구분":"시험은 제1차 시험과 제2차 시험 두 단계로 나뉩니다.","시험의 실시, 응시수수료, 시험과목, 과목 면제, 시험방법, 합격기준, 자격증 발급 등은 대통령령으로 정한다":"시험 실시, 수수료, 과목, 면제, 합격기준, 자격증 발급 등은 대통령령에서 정합니다.","식물체 피해율 65% 이상, 계약자 신청 필요":"이 경우에도 식물체 피해율이 65% 이상이어야 하고 계약자의 신청이 필요합니다.","식물체 피해율이 65%(가루쌀 60%) 이상이고 계약자가 경작불능보험금을 신청한 경우에 한한다":"경작불능보험금은 식물체 피해율이 65%(가루쌀 60%) 이상이고 계약자가 신청했을 때만 지급합니다.","신청인이 동의하지 않으면 서류를 첨부하게 한다":"신청인이 행정정보 확인에 동의하지 않으면 직접 증빙 서류를 내야 하는 방식으로 바뀝니다.","실무교육을 받는 손해평가인에게 소정의 교육비를 지급할 수 있다, 교육비를 납부하게 하는 것이 아니다":"실무교육을 받는 평가인에게는 교육비를 줄 수 있을 뿐 교육비를 걷는 것이 아닙니다.","실제 경작면적, 고사면적, 타작물 및 미보상면적, 기수확면적을 확인하는 것":"면적조사는 실제 경작한 면적에서 보상하지 않는 면적을 가려내기 위한 조사 단계입니다.","심의회는 심의 사항을 검토ㆍ조정하고 심의를 보조하게 하기 위하여 분과위원회를 둔다":"분과위원회는 심의 사항을 검토·조정하고 심의회를 돕도록 두는 하부 기구예요.","심의회는 심의에 필요하면 농업재해보험에 전문지식이 있는 자, 농업인, 농림축산업인단체 또는 이해관계자의 의견을 들어야 한다":"심의에 필요하면 전문가, 농업인, 단체, 이해관계자의 의견을 들어야 해요.","심의회는 위원장 및 부위원장 각 1명을 포함한 21명 이내의 위원으로 구성":"위원장과 부위원장 각 한 명을 포함하는 위원 수의 상한이 있어, 위원 정원이 정해진 합의제 기구입니다.","아래 각 호에 해당하는 사람이 각각 1명 이상 포함되어야 한다":"위원 중에는 법이 정한 각 분야 사람이 각각 1명 이상 들어가야 해요.","아래 기관ㆍ법인에서 손해사정 관련 업무에 3년 이상 종사한 경력자":"손해사정 관련 업무를 3년 이상 해 본 사람이 아래 기관에 있었다면 첫 단계 시험 면제 대상입니다.","약정을 체결하려는 자는 재해보험사업 약정체결신청서에 서류를 첨부하여 농림축산식품부장관 또는 해양수산부장관에게 제출":"약정을 하려는 자는 약정체결신청서에 서류를 붙여 담당 장관에게 냅니다.","약정 체결 시 제출 서류: 사업방법서, 보험약관, 보험료 및 책임준비금산출방법서, 정관":"약정을 맺을 때는 사업방법서, 약관, 보험료·책임준비금 산출방법서, 정관을 내야 해요.","약정체결 신청을 받은 장관은 행정정보의 공동이용을 통하여 법인 등기사항증명서를 확인하여야 한다":"신청을 받은 장관은 행정정보 공동이용으로 법인 등기사항증명서를 직접 대조해 보아야 합니다.","양식수산물 및 어업용 시설물에 발생하는 자연재해ㆍ질병 또는 화재":"어업재해는 양식수산물과 어업용 시설물에 생기는 자연재해, 질병, 화재를 말합니다.","양식수산물재해보험(해양수산부 소관)":"양식수산물재해보험은 해양수산부 소관이라 농업재해보험이 아닙니다.","업무 1: 피해사실의 확인 / 업무 2: 보험가액 및 손해액의 평가 / 업무 3: 그 밖의 손해평가에 필요한 사항":"손해평가사 업무는 피해사실 확인, 보험가액과 손해액 평가, 그 밖의 필요한 사항입니다.","업무 수행과 관련하여 향응을 제공받은 경우, 요령을 준수하지 않은 경우, 심신장애로 직무를 수행할 수 없게 된 경우":"향응 수수, 요령 미준수, 심신장애는 자격 취소 사유로 열거되지 않았어요.","업무위탁(제13조)에는 금융원이 없고 손해사정업자가 있다":"업무위탁 규정에는 금융원이 대상으로 없고 손해사정업자가 대상으로 들어 있습니다.","업무 정지 처분을 하려면 청문을 하여야 한다":"업무정지 처분도 하기 전에 청문을 해야 해요.","예산의 범위에서 재해보험가입자가 부담하는 보험료의 일부를 추가로 지원할 수 있다":"지방자치단체는 예산 범위에서 보험료 일부를 추가로 지원할 수 있어요.","예산의 범위에서 재해보험가입자가 부담하는 보험료의 일부와 재해보험사업자의 운영 및 관리에 필요한 비용(운영비)의 전부 또는 일부를 지원할 수 있다":"정부는 가입자 보험료의 일부와 사업자의 운영비를 예산 범위에서 지원할 수 있습니다.","오디(조사대상주수): 50주 미만 6 / 50~100 미만 7 / 100~200 미만 8 / 200~300 미만 9 / 300~400 미만 10 / 400~500 미만 11 / 500~600 미만 12 / 600주 이상 13":"오디는 조사대상주수가 50주 미만이면 6주, 600주 이상이면 13주를 표본으로 삼습니다.","오디: 결실완료 후, 결실수 조사(표본조사)":"오디 과실손해조사는 결실이 끝난 뒤 결실수를 표본조사해요.","오디 피해율 = (평년결실수 - 조사결실수 - 미보상감수결실수) ÷ 평년결실수":"오디 피해율은 평년결실수에서 조사결실수와 미보상감수결실수를 뺀 값을 평년결실수로 나눈 비율이에요.","오미자(유인틀 길이): 500m 미만 5 / 500~1,000m 미만 6 / 1,000~2,000m 미만 7 / 2,000~4,000m 미만 8 / 4,000~6,000m 미만 9 / 600m 이상 10 (고시 원문 표기가 「600m 이상」이며 6,000m 이상의 오기로 보인다)":"오미자는 유인틀 길이로 표본주를 정하며 500m 미만 5주에서 가장 큰 구간 10주까지입니다.","요청받은 자는 특별한 사유가 없으면 따라야 한다":"요청을 받은 기관은 특별한 사유가 없는 한 요청에 따라야 합니다.","용어는 재조사가 아닌 재평가":"이때 쓰는 용어는 재조사가 아니라 재평가예요.","운영비는 전부 또는 일부를 지원할 수 있다, 「하여야 한다」가 아니라 「할 수 있다」":"운영비는 전부 또는 일부를 지원할 수 있다고 되어 있어 의무가 아닙니다.","원칙은 「취소할 수 있다」이고, 제1호(거짓ㆍ부정 취득)와 제5호(업무정지 중 업무 수행)만 「취소하여야 한다」":"원칙은 취소할 수 있다는 임의 규정이고, 부정 취득과 업무정지 중 업무 수행만 의무 취소예요.","위 목적 외의 목적으로 입금된 보험금: 입금된 보험금의 2분의 1에 해당하는 액수는 압류할 수 없다":"재생산 비용 외의 목적으로 입금된 보험금은 2분의 1만 압류에서 보호됩니다.","위반하면 500만원 이하의 벌금":"회계를 구분하지 않고 처리하면 500만원 이하의 벌금이 따릅니다.","위반행위가 둘 이상이면 가장 무거운 기준에 따르고 그 2분의 1까지 늘릴 수 있다":"위반이 둘 이상이면 가장 무거운 기준을 적용하고 그 2분의 1까지 늘릴 수 있습니다.","위반행위가 둘 이상이면 무거운 기준 적용":"위반이 둘 이상이면 무거운 기준을 적용합니다.","위반행위가 둘 이상이면 무거운 처분기준에 따른다":"위반이 둘 이상이면 가장 무거운 처분 기준을 따릅니다.","위반행위의 정도, 위반횟수, 동기와 결과 등을 고려하여 개별기준 금액을 2분의 1 범위에서 줄이거나 늘릴 수 있다":"정도·횟수·동기·결과를 고려해 개별기준 금액을 2분의 1 범위에서 줄이거나 늘릴 수 있어요.","위원은 농림축산식품부장관이 임명하거나 위촉한다":"위원을 정하는 방식은 임명 또는 위촉이며, 두 방식 모두 장관의 권한에 속합니다.","위원장은 심의회를 대표하며 업무를 총괄":"위원장은 심의회를 대표하고 업무 전체를 총괄하는 사람입니다.","위원장은 회의를 소집하며 그 의장이 된다":"위원장이 회의를 소집하고 회의의 의장이 됩니다.","위 제2조의4 각 호 외에 재해보험 목적물의 선정 및 확대, 기본계획의 수립ㆍ시행, 다른 법령이 정한 사항이 더해진다":"농업재해보험심의회는 위 사항 외에 목적물 선정·확대와 기본계획 수립·시행 등도 추가로 심의합니다.","위촉 단위는 시ㆍ군ㆍ자치구별, 시ㆍ도, 읍ㆍ면ㆍ동이 아니다":"위촉 단위는 시·군·자치구별이며 시·도나 읍·면·동 단위가 아닙니다.","위촉을 취소하거나 업무정지를 명하려면 손해평가인에게 청문을 실시하여야 한다":"위촉 취소나 업무정지를 하기 전에는 평가인의 의견을 듣는 청문 절차를 반드시 거쳐야 합니다.","위탁 사무처리 경비는 기금이 부담한다":"위탁 사무를 처리하는 데 드는 경비는 기금이 부담합니다.","위탁 임명은 임원 2명(수입담당ㆍ지출원인행위담당), 직원 2명(지출원ㆍ출납원)으로 짝지어 외운다":"위탁 임명은 임원 두 자리와 직원 두 자리로 나누어 두 명씩 짝지어 두는 구조예요.","위탁한 때에는 위탁받은 자 및 위탁업무의 내용 등을 고시하여야 한다":"위탁했다면 위탁받은 자와 위탁 업무의 내용 등을 고시해야 합니다.","유자: 50주 미만 5 / 50~100 미만 6 / 100~200 미만 7 / 200~500 미만 8 / 500~800 미만 9 / 800주 이상 10":"유자도 50주 미만 5주에서 800주 이상 10주까지 같은 구간으로 표본주를 정합니다.","은행법에 따른 은행에의 예치, 국채ㆍ공채 또는 자본시장법 제4조의 증권 매입":"기금의 여유자금은 은행 예치나 국채·공채·증권 매입으로 운용할 수 있어요.","응시원서는 농림축산식품부장관이 고시하는 서식으로 제출하고, 고시된 응시수수료를 내야 한다":"응시원서는 고시된 서식으로 내고 고시된 수수료를 납부해야 해요.","이때 「보험회사」는 「보험사업자」로 본다":"이때 보험업법의 보험회사는 보험사업자로 읽어서 적용합니다.","이앙 한계일(7.31) 이후, 이앙(직파)불능 상태 및 통상적인 영농활동 실시여부 조사, 벼만 해당":"이앙불능피해조사는 이앙 한계일 이후 이앙 불가 상태와 영농활동 여부를 보며, 벼만 해당합니다.","이앙 한계일(7.31) 이후: 이앙(직파)불능피해조사, 수확완료 후 보험 종기 전: 고사나무조사":"이앙 한계일 이후에는 이앙불능피해조사를, 수확완료 후 보험 종기 전에는 고사나무조사를 해요.","이의신청 처리의 신청요건ㆍ절차ㆍ방법 등은 농림축산식품부장관 또는 해양수산부장관이 정하여 고시":"이의신청의 요건과 절차는 장관이 정해 고시합니다.","이체할 수 없으면 먼저 수급권자의 신청에 따라 다른 금융기관의 보험금수급전용계좌로 이체":"이체가 안 되면 우선 수급권자가 신청한 다른 금융기관의 전용계좌로 보냅니다.","인명 피해는 해당하지 않는다":"사람의 생명이나 신체 피해는 이 보험의 보상 대상이 아닙니다.","인삼(피해칸수): 300칸 미만 3칸 / 300~500 미만 4 / 500~700 미만 5 / 700~900 미만 6 / 900~1,200 미만 7 / 1,200~1,500 미만 8 / 1,500~1,800 미만 9 / 1,800칸 이상 10":"인삼은 피해칸수가 300칸 미만이면 3칸, 1,800칸 이상이면 10칸을 표본으로 조사합니다.","인삼 조사시기는 수확 직전, 사고접수 후 지체 없이, 수확완료 후 보험 종기 전이 아니라 피해 확인이 가능한 시기":"인삼 조사시기는 수확 직전이나 사고접수 직후, 수확완료 후가 아니라 피해 확인이 가능한 시기예요.","인삼 피해율 = (1 - 수확량 ÷ 연근별기준수확량) × 피해면적 ÷ 재배면적":"인삼 피해율은 수확량 감소 비율에 재배면적 대비 피해면적 비율을 곱해 구합니다.","일부 과목이 아니라 제1차 시험 전체":"면제는 일부 과목에 그치지 않고 제1차 시험 전체에 해당해요.","일정비율(자기부담비율별): 10%형 45%, 15%형 42%, 20%형 40%, 30%형 35%, 40%형 30%":"자기부담비율이 낮을수록 보장비율은 높아져 10%형은 45%, 40%형은 30%가 됩니다.","일정비율(자기부담비율별): 10%형 60%, 15%형 57%, 20%형 55%, 30%형 50%, 40%형 45%":"수확불능 보장비율은 자기부담비율별로 10%형 60%에서 40%형 45%까지 낮아집니다.","임산물 재배 관련 학과가 아니라 보험 관련 학과":"필요한 학과는 임산물 재배 관련이 아니라 보험 관련 학과라는 점이 다릅니다.","임의 추출은 허용된다, 전수 검증조사가 아니다":"검증조사는 임의 추출한 일부를 대상으로 하며 모든 목적물을 조사하는 전수 방식이 아닙니다.","자격시험 실시 및 관리 업무는 한국산업인력공단에 위탁할 수 있다":"시험의 운영 같은 실무는 전문 기관인 한국산업인력공단에 위임할 수 있습니다.","자격시험은 매년 1회 실시, 수급상 필요하다고 인정하면 2년마다 실시할 수 있다":"자격시험은 매년 1회 치르며 수급상 필요하면 2년마다 실시할 수도 있어요.","자격을 취득하지 않고 명의를 사용하거나 자격증을 대여받은 자에게 부과될 수 있는 벌칙은 징역 6월이 해당한다(1년 이하 징역 범위)":"명의 사용으로 징역 6월을 받을 수 있는 것은 1년 이하 징역 범위 안의 형이기 때문입니다.","자격 취소 처분을 하려면 청문을 하여야 한다":"자격을 취소하려면 청문 절차를 거쳐야 합니다.","자격 취소 처분의 세부기준은 대통령령(별표 2의3)으로 정한다":"자격 취소 처분의 세부 기준은 대통령령 별표에서 정합니다.","자기가 실시한 손해평가에 대한 검증조사, 재조사 및 재평가":"자기가 한 평가에 대한 검증조사·재조사·재평가에서도 그 사람은 빠집니다.","자기 또는 생계를 같이 하는 4촌 이내 친족(이해관계자)이 가입한 보험계약의 손해평가 — 3개월/6개월/6개월":"자신이나 생계를 같이하는 4촌 이내 친족이 가입한 계약을 평가하면 3개월, 6개월, 6개월 정지입니다.","자기 또는 이해관계자가 모집한 보험계약에 관한 손해평가":"자기나 이해관계자가 모집한 계약의 평가에서도 배제해야 해요.","자기 또는 이해관계자가 모집한 보험계약의 손해평가 — 3개월/6개월/6개월":"자신이나 이해관계자가 모집한 계약을 평가한 경우도 3개월, 6개월, 6개월입니다.","자기 또는 자기와 생계를 같이 하는 친족(이해관계자)이 가입한 보험계약에 관한 손해평가":"자기나 생계를 같이하는 친족이 가입한 계약의 평가에서는 그 사람을 배제합니다.","자기부담금 = |보험가입금액 × min(주계약피해율 - 자기부담비율, 0)|":"동상해 자기부담금은 주계약피해율이 자기부담비율에 못 미치는 만큼만 가입금액에 곱해 정해요.","자기부담금 = 보험가입금액 × 계약 시 선택한 비율":"고추의 자기부담금은 가입금액에 계약 때 선택한 비율을 곱한 금액입니다.","자기부담금 = 보험가입금액 × 자기부담비율":"옥수수 자기부담금은 가입금액에 자기부담비율을 곱한 금액입니다.","자기부담금 = 잔존보험가입금액 × 계약 시 선택한 비율":"자기부담금은 잔존보험가입금액에 계약 때 고른 비율을 곱한 금액입니다.","자료를 요청받은 관계 중앙행정기관 및 지방자치단체의 장은 특별한 사유가 없으면 요청에 따라야 한다":"통계 요청을 받은 관계 기관의 장은 정당한 사유가 없는 한 협조할 의무가 있습니다.","자연재해, 조수해(鳥獸害), 화재 및 보험목적물별로 농림축산식품부장관이 고시하는 병충해":"농작물재해보험이 보상하는 재해에는 자연재해, 조수해, 화재와 장관이 고시한 품목별 병충해가 있습니다.","자연재해, 화재 및 보험목적물별로 농림축산식품부장관이 고시하는 질병":"가축재해보험이 보상하는 재해는 자연재해, 화재, 그리고 목적물별로 고시된 질병입니다.","자연재해, 화재 및 보험목적물별로 해양수산부장관이 고시하는 수산질병":"양식수산물재해보험은 자연재해, 화재와 고시된 수산질병을 보상합니다.","자연재해 등으로 인한 피해가 대통령령으로 정하는 기준을 초과하는 경우 그 손해는 보험료 할증 시 제외하여야 한다":"피해가 대통령령 기준을 넘는 큰 손해는 보험료를 올릴 때 계산에서 빼야 합니다.","작물별로 보험가입 당시 정한 보험가액을 기준으로 산정":"생산비보장은 작물별로 가입 당시 정한 보험가액을 기준으로 삼습니다.","잔존보험가입금액 = 보험가입금액 - 보상액(기 발생 생산비보장보험금 합계액)":"잔존보험가입금액은 가입금액에서 이미 지급한 생산비보장 보상액 합계를 뺀 금액이에요.","장관(위탁받은 자 포함)은 손해평가사 시험ㆍ자격 취소ㆍ감독 사무 등에 불가피하면 주민등록번호 포함 자료를 처리할 수 있다":"시험·취소·감독 사무에 불가피하면 위탁받은 자도 주민등록번호가 포함된 자료를 처리할 수 있어요.","장관은 공정하고 객관적인 손해평가를 위해 요령에 따라 결과를 검증하기 위한 조사를 실시할 수 있다":"장관은 공정한 평가를 위해 요령에 따라 결과를 검증하는 조사를 직접 할 수도 있습니다.","장관은 보험가입자의 기준(제9조) 및 재해보험사업자에 대한 재정지원에 관한 사항(제10조제2항제3호) 등을 확인하여 지원금액을 결정ㆍ지급":"장관은 가입자 기준과 재정지원 사항 등을 확인하고 지원금액을 정해 지급합니다.","장관은 보험상품의 운영 및 개발에 필요한 지역별ㆍ재해별 통계자료를 수집ㆍ관리하여야 하며, 관계 중앙행정기관 및 지방자치단체의 장에게 자료를 요청할 수 있다":"장관은 지역별·재해별 통계자료를 수집·관리해야 하고 관계 기관에 자료를 요청할 수 있습니다.","장관은 사업결과보고서를 바탕으로 신규 보험상품의 도입 가능성 등을 검토ㆍ평가하여야 한다":"장관은 그 보고서를 바탕으로 신규 상품을 도입할 수 있는지 검토하고 평가합니다.","장관은 재해보험의 건전한 운영과 가입자 보호를 위하여 필요하면 재해보험사업자에게 업무 처리 상황의 보고 또는 관계 서류의 제출을 요구할 수 있다":"장관은 건전한 운영과 가입자 보호를 위해 사업자에게 업무 보고나 서류 제출을 요구할 수 있어요.","장관은 재해보험 제도 및 상품 개발 등을 위한 조사ㆍ연구, 관련 기술 개발 및 전문인력 양성 등의 진흥 시책을 마련하여야 한다":"장관은 제도와 상품 개발을 위한 조사·연구, 기술 개발, 전문인력 양성 등의 진흥 시책을 마련해야 합니다.","장관은 행정정보 공동이용으로 고용보험 피보험자격 이력내역서, 국민연금가입자가입증명 또는 건강보험 자격득실확인서를 확인":"장관은 행정정보 공동이용으로 고용보험·국민연금·건강보험 자료를 확인할 수 있어요.","재검토기한 3년: 숫자 3이 기준 시점과 종기일 양쪽 괄호에 공통으로 들어간다":"재검토 주기가 3년이라는 숫자가 기준 시점과 종기일 설명에 모두 들어 있어요.","재보험수수료 / 재보험 약정기간 / 재보험 책임범위 / 재보험 약정의 변경ㆍ해지 등 / 재보험금 지급 및 분쟁 / 그 밖에 재보험의 운영ㆍ관리에 관한 사항":"대통령령 사항에는 수수료, 약정기간, 책임범위, 변경·해지, 보험금 지급과 분쟁 등이 있습니다.","재정식조사: 고추, 배추(고랭지배추), 브로콜리, 양상추, 노지오이만 해당":"재정식조사는 고추, 배추, 브로콜리, 양상추, 노지오이만 대상이에요.","재조달가액 그 자체가 아니다":"재조달가액 그대로가 보험가액인 것이 아니라 감가상각을 뺀 값이에요.","재파종(당근: 고랭지당근, 가을ㆍ월동당근): 보험가입금액 × 15% × 면적피해율, 같은 요건":"고랭지당근과 가을·월동당근의 재파종은 가입금액의 15%에 면적피해율을 곱하며 요건은 같아요.","재파종조사: 무(고랭지무, 가을무(단무지무, 알타리무)), 쪽파, 시금치, 메밀만 해당":"재파종조사는 무, 쪽파, 시금치, 메밀만 대상입니다.","재평가를 결정하는 주체는 재해보험사업자다(손해평가반이 아니다)":"재평가를 할지 결정하는 사람은 사업자이고 평가반이 정하는 것이 아닙니다.","재평가에도 이의가 해결되지 않으면 농림축산식품부장관 또는 해양수산부장관이 정하는 기관에 이의신청을 할 수 있다":"재평가로도 해결되지 않으면 장관이 정한 기관에 이의신청을 할 수 있어요.","재해보험 가입규모, 가입분포 등을 고려하여 교차손해평가 대상 시ㆍ군ㆍ구(자치구)를 선정하여야 한다":"교차평가의 첫 단계는 가입 규모와 분포를 보고 대상 시·군·구를 정하는 것이에요.","재해보험가입자가 보험에 가입된 보험목적물을 양도하는 경우 양수인은 재해보험계약에 관한 양도인의 권리 및 의무를 승계한 것으로 추정한다":"보험목적물을 양도하면 양수인은 양도인의 계약상 권리와 의무를 승계한 것으로 추정됩니다.","재해보험가입자가 재해보험사업자에게 내야 할 보험료의 회수 자금":"가입자가 사업자에게 내는 보험료를 회수한 자금은 기금 재원에 들지 않아요.","재해보험가입자 보험료의 지원, 손해평가 교육비용 지출":"가입자 보험료 지원이나 손해평가 교육비는 기금 용도로 명시되지 않은 항목이에요.","재해보험가입자에게 지급하는 것이 아니다":"지급 상대는 사업자이며 가입자에게 직접 주는 것이 아닙니다.","재해보험 관련 분쟁의 조정은 금융소비자 보호에 관한 법률 제33조부터 제43조까지의 규정에 따른다":"재해보험 관련 분쟁은 금융소비자 보호법의 분쟁조정 규정에 따라 조정합니다.","재해보험 대상 농작물 분야에서 국가기술자격법에 따른 기사 이상의 자격을 소지한 사람":"대상 농작물 분야에서 기사 이상의 국가기술자격을 가진 사람도 자격이 있습니다.","재해보험 대상 농작물을 5년 이상 경작한 경력이 있는 농업인":"농작물을 5년 이상 경작한 경력이 있는 농업인이 손해평가인이 될 수 있습니다.","재해보험 대상 품목의 품종, 재배방식 등에 대한 내용을 포함":"정기교육에는 대상 품목의 품종과 재배방식 등에 관한 내용이 들어갑니다.","재해보험 및 재보험에 관한 다음 사항은 농업재해보험심의회 또는 중앙 수산업ㆍ어촌정책심의회의 심의를 거쳐야 한다":"재해보험과 재보험에 관한 아래 사항은 심의회 심의를 반드시 거쳐야 합니다.","재해보험사업에는 금융소비자 보호에 관한 법률 제45조가 적용된다":"금융소비자 보호법의 제45조 규정이 재해보험사업에도 그대로 미칩니다.","재해보험사업에는 보험업법 제104조~제107조, 제118조제1항, 제119조, 제120조, 제124조, 제127조, 제128조, 제131조~제133조, 제134조제1항, 제136조, 제162조, 제176조, 제181조제1항이 적용된다":"재해보험사업에는 보험업법의 여러 조문이 그대로 적용됩니다.","재해보험사업을 전국적으로 실시하기 전에 보험의 효용성 및 보험 실시 가능성 등을 검증하기 위하여 일정 기간 제한된 지역에서 실시하는 보험사업":"시범사업은 전국 시행에 앞서 일정 기간 제한된 지역에서 보험의 효용성과 실시 가능성을 시험하는 사업이에요.","재해보험사업을 하려는 자는 농림축산식품부장관 또는 해양수산부장관과 재해보험사업의 약정을 체결하여야 한다":"사업을 하려는 자는 먼저 담당 장관과 재해보험사업 약정을 맺어야 합니다.","재해보험사업의 약정을 체결한 자":"재해보험사업자는 재해보험사업 약정을 맺은 자를 가리킵니다.","재해보험사업자가 손해평가인을 위촉한 경우에는 그 자격을 표시할 수 있는 손해평가인증을 발급하여야 한다":"손해평가인을 위촉하면 자격을 표시하는 손해평가인증을 발급해야 합니다.","재해보험사업자가 수협중앙회, 산림조합중앙회인 경우 보험업법 제95조제1항제5호는 준용하지 않는다":"재해보험사업자가 수협중앙회나 산림조합중앙회라면 보험업법 해당 규정 하나는 준용하지 않아요.","재해보험사업자가 제10조제2항에서 준용하는 보험업법 제95조를 위반하여 보험안내를 한 경우":"사업자가 보험업법 준용 규정을 어겨 보험안내를 하면 과태료 가운데 가장 높은 단계에 해당합니다.","재해보험사업자는 공정하고 객관적인 손해평가를 위하여 동일 시ㆍ군ㆍ구(자치구) 내에서 교차손해평가를 수행할 수 있다":"교차손해평가는 공정성을 위해 같은 시·군·구 안에서 할 수 있어요.","재해보험사업자는 보험가입촉진계획을 매년 수립하여 농림축산식품부장관 또는 해양수산부장관에게 제출하여야 한다":"재해보험사업자는 해마다 가입 촉진 계획을 세워 담당 장관에게 내야 합니다.","재해보험사업자는 보험가입촉진계획을 매년 수립하여 제출한다, 3년 단위가 아니다":"가입촉진계획은 3년 단위가 아니라 해마다 세워 내야 해요.","재해보험사업자는 보험료율을 객관적이고 합리적인 통계자료를 기초로 보험목적물별 또는 보상방식별로 산정":"재해보험사업자는 객관적이고 합리적인 통계를 바탕으로 보험료율을 산정해야 합니다.","재해보험사업자는 보험목적물에 관한 지식과 경험을 갖춘 사람 또는 그 밖의 관계 전문가를 손해평가인으로 위촉하여 손해평가를 담당하게 할 수 있다":"사업자는 지식과 경험을 갖춘 사람을 손해평가인으로 위촉해 손해평가를 맡길 수 있습니다.","재해보험사업자는 보험약관안과 보험료율안에 대통령령으로 정하는 변경이 예정된 경우 이를 공고하고 필요하면 이해관계자의 의견을 수렴하여야 한다":"약관안이나 보험료율안에 대통령령이 정한 변경이 예정되면 공고하고 필요하면 의견을 들어야 해요.","재해보험사업자는 보험의 효용성 및 보험 실시 가능성 등을 종합적으로 고려하여 위 재해 범위 안에서 다양한 보험상품을 운용할 수 있다":"재해보험사업자는 정해진 재해 범위 안에서라면 여러 형태의 보험상품을 운영할 수 있어요.","재해보험사업자는 사고 예방을 위하여 보험가입자가 납입한 보험료의 일부를 되돌려줄 수 있다":"사고 예방을 위해 사업자가 가입자에게 낸 보험료의 일부를 돌려줄 수 있어요.","재해보험사업자는 손해사정사가 법령을 위반한 경우 적정한 제재가 가능하도록 구체적 적용기준을 마련하여 시행하여야 한다":"사업자는 손해사정사가 법령을 위반했을 때 제재할 수 있도록 구체적 적용기준을 만들어 시행해야 합니다.","재해보험사업자는 손해평가결과와 손해평가업무를 수행한 손해평가반 구성원을 기록할 수 있도록 현지조사서를 마련하여야 한다, 마련 주체는 재해보험사업자":"현지조사서를 마련하는 주체는 평가반이 아니라 재해보험사업자입니다.","재해보험사업자는 손해평가를 하는 경우":"손해평가반을 꾸리는 주체는 평가인이 아니라 재해보험사업자입니다.","재해보험사업자는 손해평가반으로 하여금 재해발생 전부터 보험품목에 대한 생육상황을 조사하게 할 수 있다":"사업자는 평가반이 재해 전부터 품목의 생육상황을 조사하게 할 수 있어요.","재해보험사업자는 손해평가인으로 위촉된 사람에게 보험에 관한 기초지식, 보험약관 및 손해평가요령 등에 관한 실무교육을 하여야 한다":"사업자는 위촉한 손해평가인에게 보험 기초지식, 약관, 평가요령 등을 실무교육으로 가르쳐야 해요.","재해보험사업자는 손해평가인이 다음에 해당하게 되거나 위촉 당시 해당하는 자였음이 판명된 때 위촉을 취소하여야 한다":"평가인이 아래 사유에 해당하게 되거나 위촉 당시 해당했음이 드러나면 사업자는 위촉을 취소해야 해요.","재해보험사업자는 손해평가인이 다음에 해당하면 6개월 이내의 기간을 정하여 업무의 정지를 명하거나 위촉 해지 등을 할 수 있다":"평가인이 아래에 해당하면 사업자는 6개월 이내 업무정지나 위촉 해지 등을 할 수 있어요.","재해보험사업자는 수급권자의 신청이 있는 경우 보험금을 수급권자 명의의 지정된 계좌(보험금수급전용계좌)로 입금하여야 한다":"보험금은 수급권자가 신청하면 본인 명의의 지정 계좌인 보험금수급전용계좌에 입금해야 합니다.","재해보험사업자는 신규 보험상품을 개발하거나 도입하려는 경우 등 필요하면 장관과 협의하여 시범사업을 할 수 있다":"신규 상품을 개발하거나 도입할 때 사업자는 장관과 협의해 시범사업을 할 수 있어요.","재해보험사업자는 요령의 효율적인 운용 및 시행을 위하여 필요한 세부적인 사항을 규정한 손해평가업무방법서를 작성하여야 한다":"사업자는 요령을 잘 운용하려고 세부 사항을 담은 손해평가업무방법서를 작성해야 합니다.","재해보험사업자는 위촉된 손해평가인을 대상으로 농업재해보험에 관한 기초지식, 보험상품 및 약관, 손해평가의 방법 및 절차 등 손해평가에 필요한 실무교육을 실시하여야 한다":"사업자는 위촉된 평가인에게 기초지식, 상품·약관, 평가 방법과 절차 등을 실무교육해야 합니다.","재해보험사업자는 재해보험사업을 원활히 수행하기 위하여 필요하면 보험모집 및 손해평가 등 재해보험 업무의 일부를 대통령령으로 정하는 자에게 위탁할 수 있다":"사업자는 보험모집과 손해평가 등 업무 일부를 대통령령이 정한 자에게 위탁할 수 있습니다.","재해보험사업자는 재해보험사업의 회계를 다른 회계와 구분하여 회계처리함으로써 손익관계를 명확히 하여야 한다":"재해보험사업의 회계는 다른 회계와 구분해 처리해서 손익이 분명히 드러나게 해야 합니다.","재해보험사업자는 정기교육 대상자에게 소정의 교육비를 지급할 수 있다":"정기교육을 받는 사람에게 교육비를 지급할지는 사업자의 재량으로 정할 수 있습니다.","재해보험사업자는 특별한 사유가 없는 한 응하여야 하고 결과를 농림축산식품부장관에게 제출한다":"사업자는 특별한 사유가 없으면 응해야 하고 결과를 장관에게 제출합니다.","재해보험사업자는 특별한 사유가 없으면 그 조치를 실시해야 한다":"사업자는 특별한 사유가 없으면 요구받은 조치를 이행해야 해요.","재해보험사업자는 피해 발생 시 원활한 손해평가를 위하여 농업재해보험이 실시되는 시ㆍ군ㆍ자치구별 보험가입자의 수 등을 고려하여 적정 규모의 손해평가인을 위촉할 수 있다":"사업자는 가입자 수 등을 고려해 적정 규모의 손해평가인을 위촉할 수 있어요.","재해보험사업자 및 법 제14조에 따라 손해평가 업무를 위탁받은 자는 손해평가 업무를 원활히 수행하기 위하여 손해평가보조인을 운용할 수 있다":"사업자와 업무를 위탁받은 자는 평가 업무를 원활히 하려고 손해평가보조인을 운용할 수 있어요.","재해보험사업자 및 법 제25조의2에 따라 농어업재해보험사업의 관리를 위탁받은 기관(사업 관리 위탁 기관)은 손해평가를 실시한 보험목적물 중에서 일정수를 임의 추출하여 검증조사를 할 수 있다":"사업자와 사업 관리 위탁 기관은 평가한 목적물 중 일부를 임의 추출해 검증조사를 할 수 있어요.","재해보험사업자 상호간이 아니다":"교차손해평가는 사업자끼리 하는 것이 아니라 평가인끼리 하는 방식이에요.","재해보험사업자의 발기인, 설립위원, 임원, 집행간부, 일반간부직원, 파산관재인 및 청산인이 보험업법 제120조에 따른 책임준비금과 비상위험준비금을 계상하지 아니하거나 따로 작성한 장부에 각각 기재하지 아니한 경우":"준비금 계상이나 장부 기재를 하지 않은 임원 등에게는 과태료가 따릅니다.","재해보험에 가입할 수 있는 자: 농림업, 축산업, 양식수산업에 종사하는 개인 또는 법인, 법인도 가입할 수 있다":"농림업, 축산업, 양식수산업에 종사하는 개인과 법인이 재해보험에 가입할 수 있습니다.","재해보험의 보험금을 지급받을 권리는 압류할 수 없다":"보험금을 받을 권리는 채권자가 압류하지 못하도록 법으로 막아 둔 권리입니다.","적과 종료 후: 적과 후 착과수조사(적과전종합위험방식)":"적과 후 착과수조사는 적과 종료 후에 하는 적과전종합위험방식의 조사입니다.","적과 후 착과수 조사 — 적과 종료 후, 해당 농지의 적과 종료 후 총 착과 수를 조사(표본조사), 피해와 관계없이 전 과수원 조사":"적과 후 착과수 조사는 피해와 상관없이 과수원 전체의 적과 종료 후 총 착과 수를 표본조사합니다.","적과후착과수조사를 통해 산정한 기준수확량에 보험가입 당시의 단위당 가입가격을 곱하여 산정":"적과전종합위험방식 보험가액은 적과 후 착과수조사로 구한 기준수확량에 가입가격을 곱합니다.","적용가격은 보험사고가 발생한 때와 곳에서의 시장가격 등을 감안하여 보험약관에서 정한 방법에 따라 산정, 곱하는 값은 시장가격이 아니라 적용가격":"적용가격은 사고 때 그 장소의 시장가격 등을 약관 방법에 따라 산정한 값이며 시장가격 그대로는 아닙니다.","전년도의 성과분석 및 해당 연도의 사업계획 / 해당 연도의 보험상품 운영계획 / 농어업재해보험 교육 및 홍보계획 / 보험상품의 개선ㆍ개발계획 / 그 밖에 가입 촉진을 위해 필요한 사항":"촉진계획에는 전년도 성과 분석, 올해 사업·상품 운영, 교육 홍보, 상품 개선 계획 등을 적습니다.","전수조사: 조사대상 목적물을 전부 조사":"전수조사는 조사 대상 목적물을 빠짐없이 전부 조사하는 방법이에요.","절차ㆍ방법 등은 농림축산식품부장관 또는 해양수산부장관이 정한다":"교차손해평가의 절차와 방법은 담당 장관이 정합니다.","정보보호 관련 법령 위반: 1차 위촉해지":"정보보호 법령을 위반하면 처음부터 위촉해지가 가능한 단계예요.","정보통신장애나 그 밖에 대통령령으로 정하는 불가피한 사유로 이체할 수 없을 때는 현금 지급 등 대통령령으로 정하는 바에 따라 지급할 수 있다":"정보통신장애 같은 불가피한 사유로 이체가 안 되면 현금 지급 등 다른 방법으로 줄 수 있어요.","정부는 농어업인의 재해대비의식을 고양하고 재해보험의 가입을 촉진하기 위하여 교육ㆍ홍보를 하여야 한다":"정부는 농어업인의 재해대비의식을 높이고 가입을 늘리려고 교육과 홍보를 해야 합니다.","정부는 보상하는 재해의 범위를 확대하기 위하여 노력하여야 한다":"정부는 보상하는 재해의 범위를 넓히려고 노력하여야 합니다.","정부는 보험가입자에 대한 정책자금 지원 및 신용보증 지원 등을 할 수 있다":"정부는 가입자에게 정책자금 지원이나 신용보증 지원 등을 할 수 있어요.","정부는 보험목적물의 범위를 매년 확대하기 위하여 노력하여야 한다":"정부는 보험으로 보호하는 대상이 해마다 넓어지도록 힘써야 할 의무가 있어요.","정부는 시범사업의 원활한 운영을 위하여 필요한 지원을 할 수 있다":"정부는 시범사업이 원활히 운영되도록 필요한 지원을 할 수 있습니다.","정부는 재해보험에 관한 재보험사업을 할 수 있다":"재보험은 보험사업자가 진 책임을 정부가 다시 인수하는 보험으로, 정부가 직접 운영할 수 있습니다.","정부출연연구기관 등의 설립ㆍ운영 및 육성에 관한 법률 제8조에 따라 설립된 연구기관":"정부출연연구기관법에 따라 세워진 연구기관도 통계 업무를 위탁받을 수 있어요.","정식(파종)~수확 종료, 보상하는 재해 전부, 사고발생 시마다: ①재배일정 확인 ②경과비율 산출 ③피해율 산정 ④병충해 등급별 인정비율 확인(노지 고추만 해당)":"생산비 피해조사는 사고 때마다 재배일정, 경과비율, 피해율, 병충해 등급별 인정비율(노지 고추만)을 확인합니다.","정지ㆍ무효 처분을 받은 사람, 자격이 취소된 사람은 그 처분이 있은 날부터 2년이 지나지 아니하면 시험에 응시하지 못한다":"정지·무효 처분이나 자격 취소를 받은 사람은 처분일부터 2년이 지나야 다시 응시할 수 있습니다.","제10조제1항을 위반하여 모집을 한 자":"정해진 자격 없이 모집을 한 사람은 1년 이하 징역 또는 1천만원 이하 벌금에 처해요.","제10조제2항에서 준용하는 보험업법 제95조를 위반하여 보험안내를 한 자로서 재해보험사업자가 아닌 자":"사업자가 아닌 사람이 보험안내 규정을 어겨도 과태료 대상이 됩니다.","제11조의4제6항을 위반하여 다른 사람에게 손해평가사의 명의를 사용하게 하거나 자격증을 대여한 자":"손해평가사의 이름을 다른 사람이 쓰게 하거나 자격증을 빌려준 사람도 같은 벌칙입니다.","제11조의4제7항을 위반하여 손해평가사의 명의를 사용하거나 자격증을 대여받은 자 또는 명의 사용이나 자격증 대여를 알선한 자":"이름을 쓰거나 자격증을 빌린 사람, 알선한 사람도 같은 벌칙 대상이에요.","제11조제2항 후단을 위반하여 고의로 진실을 숨기거나 거짓으로 손해평가를 한 자":"일부러 진실을 숨기거나 거짓으로 손해평가를 한 사람도 같은 벌칙을 받습니다.","제15조를 위반하여 회계를 처리한 자(재해보험사업의 회계를 다른 회계와 구분하지 않은 자)":"회계처리를 구분하지 않은 사람에게는 벌금형이 내려지며 이는 가장 가벼운 단계의 벌칙입니다.","제1차ㆍ제2차 공통: 매 과목 100점 만점에 매 과목 40점 이상, 전 과목 평균 60점 이상":"제1차·제2차 합격기준은 과목당 40점 이상이고 전 과목 평균이 60점 이상이어야 합니다.","제1차 시험 과목(2026-08-04 개정 별표 2의2): 농어업재해보험법령(농어업재해보험법, 시행령, 손해평가 요령) 및 상법 보험편 / 농학개론 중 재배학 및 가축사양학 / 작물학개론 중 식량작물학 및 원예작물학":"제1차 시험 과목은 농어업재해보험법령과 상법 보험편, 재배학 및 가축사양학, 식량작물학 및 원예작물학입니다.","제1차 시험에 합격한 사람은 다음 회에 한정하여 제1차 시험을 면제한다":"제1차 시험 합격자는 다음 회 시험에 한하여 제1차를 면제받습니다.","제1차 시험은 선택형이 원칙이며 단답형 또는 기입형을 병행할 수 있다":"제1차 시험은 선택형이 원칙이고 단답형이나 기입형을 함께 낼 수 있습니다.","제1항, 제2항 제1호, 제3항(전체)":"제1항, 제2항 제1호, 제3항 전체는 두 장관이 과태료를 부과합니다.","제1항 제1호~제5호의 업무 / 재해보험사업의 약정 체결 관련 업무 / 손해평가사 제도 운용 관련 업무 / 그 밖에 재해보험사업과 관련하여 장관이 위탁하는 업무":"금융원에 위탁할 수 있는 업무에는 위 업무, 약정 체결 관련 업무, 손해평가사 제도 운용 관련 업무 등이 있어요.","제29조에 따른 보고 또는 관계 서류 제출을 하지 아니하거나 거짓으로 한 자":"보고나 서류 제출을 안 하거나 거짓으로 한 사람도 과태료를 받습니다.","제2차 시험 과목: 농작물재해보험 및 가축재해보험의 이론과 실무 / 농작물재해보험 및 가축재해보험 손해평가의 이론과 실무":"제2차 시험 과목은 농작물·가축재해보험의 이론과 실무, 손해평가의 이론과 실무예요.","제2차 시험은 서술형이 원칙이며 단답형 또는 기입형을 병행할 수 있다":"제2차 시험은 서술형을 기본으로 하되 단답형이나 기입형 문제를 섞어 낼 수 있습니다.","제2차 시험은 제1차 시험 합격자와 제1차 시험 면제자를 대상으로 한다":"제2차 시험은 제1차 합격자와 제1차 면제자만 응시 대상이에요.","제2항 제2호(보험업법 제131조 명령 위반)와 제2항 제3호(제133조 검사 거부ㆍ방해ㆍ기피)":"보험업법 명령 위반과 검사 거부·방해·기피는 금융위원회가 과태료를 부과합니다.","제4항 제1호 위원(학식ㆍ경험자)의 임기는 3년":"학식·경험자 위원의 임기는 3년으로 정해져 있습니다.","제출 기한은 해당 연도 1월 31일":"촉진계획의 제출 기한은 해당 연도 1월 31일입니다.","제현율이 65%(가루쌀 70%) 미만으로 떨어져 정상 벼로서 출하가 불가능하게 되고 계약자가 수확불능보험금을 신청한 경우에 한한다":"수확불능(벼)은 제현율이 65%(가루쌀 70%) 미만으로 떨어져 정상 출하가 불가능하고 계약자가 신청했을 때 지급해요.","조교수 이상으로 고등교육법 제2조에 따른 학교에서 농작물재배 관련학을 3년 이상 교육한 경력":"대학 조교수 이상으로 농작물재배 관련학을 3년 이상 가르친 경력이 있으면 해당됩니다.","조사대상나무수 = 실제결과나무수 - 고사나무수 - 미보상나무수 - 수확완료나무수 - 수확불능나무수":"조사대상나무수는 실제결과나무수에서 고사·미보상·수확완료·수확불능 나무수를 뺀 값이에요.","조사대상면적 = 실제 경작면적 - 고사면적 - 타작물 및 미보상면적 - 기수확면적":"조사대상면적은 실제 경작면적에서 고사·타작물 및 미보상·기수확 면적을 뺀 값입니다.","주계약피해율 = {(등급 내 피해과실수 + 등급외 피해과실수 × 50%) ÷ 기준과실수} × (1 - 미보상비율)":"주계약피해율은 등급외 피해과실수를 50%만 반영한 피해과실 비율에 미보상비율을 반영한 값입니다.","주체: 농림축산식품부장관 또는 해양수산부장관":"정기교육을 실시하는 주체는 농림축산식품부장관 또는 해양수산부장관입니다.","지원금을 받으려는 재해보험사업자는 재해보험 가입현황서나 운영비 사용계획서를 농림축산식품부장관 또는 해양수산부장관에게 제출":"지원금을 받으려는 사업자는 가입현황서나 운영비 사용계획서를 담당 장관에게 내야 해요.","직전 손해평가일로부터 30일 이내의 보험가입자간 상호 손해평가":"직전 손해평가일부터 30일 이내의 가입자끼리는 서로 평가하지 못합니다.","착과감소보험금 = (착과감소량 - 미보상감수량 - 자기부담감수량) × 가입가격 × 보장수준(50%, 70%)":"착과감소보험금은 착과감소량에서 미보상감수량과 자기부담감수량을 빼고 가입가격과 보장수준(50%, 70%)을 곱한 값이에요.","착과수조사 해당 품목에 복분자는 없다(2026 기출 정답), 감귤은 만감류만 해당, 온주밀감류는 과실손해조사":"복분자는 착과수조사 대상이 아니고, 감귤은 만감류만 착과수조사를 하며 온주밀감류는 과실손해조사를 합니다.","착과피해조사(사과ㆍ배ㆍ단감ㆍ떫은감): 수확 직전, 달려있는 과실 중 재해로 인한 피해과실수 조사, 표본조사":"착과피해조사는 수확 직전에 달린 과실 중 재해 피해과실수를 표본조사합니다.","착과피해조사 — 수확 직전, 달려있는 과실 중 재해로 인한 피해과실수 조사, 약관의 과실피해분류기준에 따라 구분(표본조사)":"착과피해조사는 수확 직전에 달려 있는 과실 중 재해 피해과실수를 표본조사하는 것입니다.","참깨, 녹두: 1,000㎡ 미만 3 / 1,000~2,500 미만 4 / 2,500~5,000 미만 5 / 5,000~7,500 미만 6 / 7,500~10,000 미만 7 / 10,000㎡ 이상 8 (원문 「7,500 이상 6,000 미만」은 7,500~10,000 미만으로 풀이)":"참깨·녹두는 1,000㎡ 미만 3구간에서 10,000㎡ 이상 8구간까지 표본구간을 정합니다.","참다래ㆍ블루베리: 50주 미만 5 / 50~100 미만 6 / 100~200 미만 7 / 200~500 미만 8 / 500~800 미만 9 / 800주 이상 10":"참다래와 블루베리는 50주 미만 5주에서 800주 이상 10주까지 표본주를 정해요.","청문에 응하지 않으면 서면으로 취소 또는 정지를 통보할 수 있다":"청문에 응하지 않은 평가인에게는 서면 통보만으로도 취소나 정지 처분을 할 수 있다는 예외입니다.","최종 합격자가 결정되면 인터넷 홈페이지에 공고":"합격자 확정 뒤에는 누구나 볼 수 있도록 인터넷 홈페이지에 발표하는 절차를 거칩니다.","타지역 조사 가능여부는 지역손해평가인 선발 시 고려사항":"타지역 조사 가능 여부는 평가인 선발 때 고려하는 사항이에요.","통계위탁(제21조)에는 금융원이 있고 중앙회가 있다":"통계위탁 규정에는 금융원과 각 중앙회가 모두 위탁 대상으로 나옵니다.","통계의 수집ㆍ관리, 조사ㆍ연구 등의 업무는 대통령령으로 정하는 자에게 위탁할 수 있다":"통계의 수집·관리와 조사·연구 업무는 대통령령이 정한 자에게 위탁할 수 있어요.","통지 상대는 보험가입자, 제출 상대는 재해보험사업자, 장관에게 보고하거나 장관에게 제출하는 것이 아니다":"통지 상대는 가입자, 제출 상대는 사업자이고 장관은 해당하지 않습니다.","특별시ㆍ광역시ㆍ도ㆍ특별자치도 또는 시(특별자치시, 행정시 포함)ㆍ군ㆍ자치구":"보험료율은 시·도 또는 시·군·자치구 같은 행정구역을 단위로 산정합니다.","평가인 2인+보조인 3인 구성이 가능했음":"그래서 평가인 2인에 보조인 3인으로 짝을 짜는 것이 가능했어요.","평년수확량ㆍ보장수확량이 아니다":"이때 곱하는 수량은 평년수확량이나 보장수확량이 아니라 기준수확량입니다.","포함사항(시행령): 농어업재해보험에 관한 기초지식 / 농어업재해보험의 종류별 약관 / 손해평가의 절차 및 방법 / 그 밖에 장관이 정하는 사항":"정기교육의 내용은 기초지식, 종류별 약관, 평가 절차와 방법, 장관이 정하는 사항으로 이루어집니다.","포함사항: 사업운영 실적 / 문제점 및 제도개선 / 사업의 중단ㆍ연장 및 확대 등":"보고서에는 운영 실적, 문제점과 제도 개선, 사업의 중단·연장·확대가 포함됩니다.","표고버섯(원목재배)(피해원목수): 1,000본 이하 10 / 1,300본 이하 14 / 1,500본 이하 16 / 1,800본 이하 18 / 2,000본 이하 20 / 2,300본 이하 24 / 2,300본 초과 26":"표고버섯 원목재배는 피해원목수가 많을수록 표본이 늘어 1,000본 이하 10에서 2,300본 초과 26까지입니다.","표본구간은 별표 2의2에 따라 산정":"표본구간의 수도 별표 2의2에 따라 산정합니다.","표본나무는 별표 2의2에 따라 산정":"표본나무 수는 별표에 따라 정해집니다.","표본조사: 재해보험사업자가 통계이론을 기초로 산정한 조사표본에 대해 조사":"표본조사는 사업자가 통계이론으로 정한 표본만 골라 조사하는 방법입니다.","표준피해율(10a 기준) = (30,000 - 식물체 주수) ÷ 30,000":"표준피해율은 30,000에서 실제 식물체 주수를 뺀 값을 30,000으로 나눈 비율입니다.","품종ㆍ재배방식ㆍ수령별 실제결과(열매맺음)나무수, 고사나무수, 미보상나무수, 수확완료나무수를 확인하는 것":"과수원 나무조사는 품종·재배방식·수령별로 실제결과나무수, 고사나무수, 미보상나무수, 수확완료나무수를 확인하는 일입니다.","풍수해ㆍ지진재해보험법에 따른 풍수해ㆍ지진재해보험에 가입한 자가 동일한 보험목적물을 대상으로 재해보험에 가입하는 경우 정부는 재정지원을 하지 아니한다":"풍수해·지진재해보험에 이미 든 사람이 같은 목적물로 재해보험에 가입하면 정부는 재정지원을 하지 않습니다.","피해목적물의 재조달가액에서 내용연수에 따른 감가상각률을 적용한 감가상각액을 차감하여 산정":"보험가액은 재조달가액에서 내용연수에 따른 감가상각액을 뺀 금액입니다.","피해사실확인조사 — 사고접수 후 지체 없이, 낙엽피해 정도 조사(표본조사), 단감ㆍ떫은감에 대해서만 실시":"낙엽피해 정도를 표본조사하는 피해사실확인조사는 단감과 떫은감에만 합니다.","피해사실확인조사 — 사고접수 후 지체 없이, 보상하는 재해로 인한 피해발생 여부 조사, 피해사실이 명백한 경우 생략 가능":"피해사실확인조사는 사고 접수 후 곧바로 보상 재해로 인한 피해 발생 여부를 조사하며, 명백하면 생략할 수 있습니다.","피해사실확인조사 — 사고접수 후 지체 없이, 우박으로 인한 유과(어린과실) 및 꽃(눈) 등의 타박비율 조사(표본조사), 적과종료 이전 특정위험 5종 한정 보장 특약 가입건에 한함":"우박 피해는 유과와 꽃의 타박비율을 표본조사하며, 특약에 가입한 건에만 해당해요.","피해율(7월 31일 이전 사고) = (평년수확량 - 수확량 - 미보상감수량) ÷ 평년수확량":"7월 31일 이전 사고의 피해율은 평년수확량에서 수확량과 미보상감수량을 뺀 비율입니다.","피해율(8월 1일 이후 사고) = (1 - 수확전사고 피해율) × 경과비율 × 결과지 피해율":"8월 1일 이후 사고는 수확전사고 피해율을 제외하고 경과비율과 결과지 피해율을 곱해 피해율을 구합니다.","피해율(감자ㆍ복숭아ㆍ가을배추(병충해보장형)) = {(평년수확량 - 수확량 - 미보상감수량) + 병충해감수량} ÷ 평년수확량":"감자·복숭아·가을배추(병충해보장형)는 병충해감수량을 더한 뒤 평년수확량으로 나눠 피해율을 구합니다.","피해율(감자ㆍ복숭아ㆍ가을배추(병충해보장형) 제외) = (평년수확량 - 수확량 - 미보상감수량) ÷ 평년수확량":"일반 품목의 피해율은 평년수확량에서 수확량과 미보상감수량을 뺀 값을 평년수확량으로 나눈 비율이에요.","피해율(배추, 무, 파, 시금치, 양상추) = 면적피해율 × 평균손해정도비율 × (1 - 미보상비율), 피해율(메밀) = 면적피해율 × (1 - 미보상비율)":"메밀은 평균손해정도비율을 곱하지 않고 면적피해율에 미보상 비율만 반영해 피해율을 구해요.","피해율: 병충해가 없는 경우 면적피해율 × 평균손해정도비율 × (1 - 미보상비율) × 경과비율, 병충해가 있는 경우 면적피해율 × 평균손해정도비율 × (1 - 미보상비율) × 병충해 등급별 인정비율 × 경과비율":"고추 피해율은 병충해가 있으면 병충해 등급별 인정비율을 추가로 곱해서 계산해요.","피해율 = (기준수입 - 실제수입) ÷ 기준수입":"농업수입 피해율은 기준수입에서 실제수입을 뺀 값을 기준수입으로 나눈 비율입니다.","피해율 = (등급내 피해과실수 + 등급외 피해과실수 × 50%) ÷ 기준과실수 × (1 - 미보상비율) (2023 기출 선지에서는 70%로 제시)":"감귤 피해율은 등급외 피해과실수를 50%만 반영해 기준과실수로 나누고 미보상비율을 반영합니다.","피해율 = (평년수확량 - 수확량 - 미보상감수량) ÷ 평년수확량":"이때 피해율도 평년수확량에서 수확량과 미보상감수량을 뺀 값의 평년수확량 대비 비율입니다.","피해 확인이 가능한 시기: 인삼 수확량조사":"인삼 수확량조사는 피해 확인이 가능한 시기에 합니다.","필요하면 정보통신망 또는 전자우편 등 전자적 방식을 이용할 수 있다":"필요하면 정보통신망이나 전자우편 같은 전자적 방식도 쓸 수 있어요.","필지가 2개 이상이어도, 지번이 2개 이상이어도 하나의 경작지이면 하나의 농지가 될 수 있다":"필지나 지번이 두 개 이상이어도 하나의 경작지이면 하나의 농지가 될 수 있습니다.","하나의 보험가입금액에 해당하는 토지로서, 필지(지번) 등과 관계없이 농작물을 재배하는 하나의 경작지":"농지는 하나의 보험가입금액에 해당하며 필지와 상관없이 농작물을 재배하는 한 덩이 경작지입니다.","하우스 등 원예시설과 축사 건물은 7영업일을 초과해 제출할 수 있다":"원예시설과 축사 건물은 기한 안에 제출한다는 원칙의 예외로 그 기한을 넘겨도 됩니다.","학점인정 등에 관한 법률 제8조에 따라 전문대학 보험 관련 학과 졸업자(졸업예정자 포함)와 같은 수준 이상의 학력이 있다고 인정받은 사람이나, 고등교육법 제2조에 따른 학교에서 80학점(보험 관련 과목 학점 45학점 이상) 이상을 이수한 사람 등 7호와 같은 수준 이상의 학력이 있다고 인정되는 사람":"학점인정법에 따라 전문대 보험 관련 학과와 같은 학력이 인정되거나 80학점 이상을 이수한 사람도 해당합니다.","합격자에게 손해평가사 자격증을 발급":"합격자에게는 자격증을 교부하는 절차가 이어져 손해평가사의 자격을 확인해 줍니다.","해당농지의 최초 품종 수확 직전 총 착과 수를 조사, 피해와 관계없이 전 과수원 조사(표본조사), 포도, 복숭아, 자두, 감귤(만감류), 사과, 배, 단감, 떫은감만 해당":"착과수조사는 최초 품종 수확 직전에 피해와 상관없이 과수원 전체를 표본조사하며 포도·복숭아 등 지정 품목만 대상입니다.","해당 연도 1월 31일까지 제출":"제출 시한은 해당 연도 1월 31일입니다.","해양수산부장관과 협의를 거쳐 기금의 관리ㆍ운용에 관한 사무의 일부를 농업정책보험금융원에 위탁할 수 있다":"협의를 거쳐 기금 관리·운용 사무 일부를 농업정책보험금융원에 위탁할 수 있어요.","해양수산부장관은 해당하지 않는다":"해양수산부장관은 손해평가사 제도 운영 주체에 해당하지 않아요.","해양수산부장관이 고시하는 양식수산물을 양식하는 자":"해양수산부장관이 고시한 양식수산물을 양식하는 사람이 양식수산물재해보험의 가입 대상입니다.","해촉하거나 업무정지를 명한 때에는 지체 없이 이유를 기재한 문서로 손해평가인에게 통지":"해촉하거나 정지를 명하면 이유를 적은 문서로 곧바로 평가인에게 알려야 해요.","현장조사, 서면조사, 통계조사, 문헌조사 등":"조사 방법에는 현장·서면·통계·문헌조사 등이 있습니다.","회의는 재적위원 3분의 1 이상의 요구가 있을 때 또는 위원장이 필요하다고 인정할 때 소집":"재적위원 3분의 1 이상이 요구하거나 위원장이 필요하다고 보면 회의를 소집해요.","회의는 재적위원 과반수의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결":"재적위원 과반수가 출석해야 회의를 열 수 있고 출석위원 과반수가 찬성하면 의결됩니다.","회의에 출석한 위원에게는 예산의 범위에서 수당, 여비, 그 밖의 경비를 지급할 수 있다, 공무원인 위원이 소관 업무와 직접 관련하여 출석한 경우는 제외":"출석한 위원에게는 예산 범위에서 수당과 여비를 줄 수 있으나, 소관 업무로 출석한 공무원 위원은 제외합니다.","횟수는 최근 1년간 같은 위반으로 제재받은 경우에 적용":"가중의 기준이 되는 횟수는 위반 전 1년 안에 같은 위반으로 받은 제재만 합산합니다.","효율적 추진을 위해 수행하는 업무 1: 재해보험사업의 관리ㆍ감독":"장관은 재해보험사업을 효율적으로 추진하려고 사업의 관리와 감독을 합니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
